package agent

// CapabilityDeclarer is implemented by agents that declare their capabilities
// at registration time (e.g., external plugin agents). The As* helper functions
// below use this interface to gate capability access: an agent must both implement
// the optional interface AND declare the capability as true.
//
// Built-in agents (Claude Code, Gemini CLI, etc.) do NOT implement this interface.
// For those agents, the As* helpers fall through to a direct type assertion,
// preserving existing behavior.
type CapabilityDeclarer interface {
	DeclaredCapabilities() DeclaredCaps
}

// DeclaredCaps enumerates the optional interfaces an agent claims to support.
// JSON tags match the external agent protocol schema so external.InfoResponse
// can deserialize directly into this type.
//
// Not every optional interface appears here: built-in-only capabilities that
// have no external-protocol equivalent (SessionBaseDirProvider, ModelExtractor,
// SkillEventExtractor, TranscriptSanitizer, TranscriptFetcher) are intentionally
// excluded — their As* helpers resolve by type assertion alone (see
// builtinCapability), with no DeclaredCaps gate.
type DeclaredCaps struct {
	Hooks                  bool `json:"hooks"`
	TranscriptAnalyzer     bool `json:"transcript_analyzer"`
	TranscriptPreparer     bool `json:"transcript_preparer"`
	TokenCalculator        bool `json:"token_calculator"`
	CompactTranscript      bool `json:"compact_transcript"`
	TextGenerator          bool `json:"text_generator"`
	StreamingTextGenerator bool `json:"streaming_text_generator"`
	HookResponseWriter     bool `json:"hook_response_writer"`
	SubagentAwareExtractor bool `json:"subagent_aware_extractor"`
}

// declaredCapability returns the agent as T if it both implements T and (for
// CapabilityDeclarer agents) has the capability selected by declared set to true.
func declaredCapability[T any](ag Agent, declared func(DeclaredCaps) bool) (T, bool) {
	t, ok := builtinCapability[T](ag)
	if !ok {
		return t, false
	}
	if cd, ok := ag.(CapabilityDeclarer); ok {
		return t, declared(cd.DeclaredCapabilities())
	}
	return t, true
}

// builtinCapability returns the agent as T by type assertion alone, for
// built-in-only capabilities that have no DeclaredCaps gate.
func builtinCapability[T any](ag Agent) (T, bool) {
	var zero T
	if ag == nil {
		return zero, false
	}
	t, ok := ag.(T)
	if !ok {
		return zero, false
	}
	return t, true
}

// AsHookSupport returns the agent as HookSupport if it both implements the
// interface and (for CapabilityDeclarer agents) has declared the capability.
func AsHookSupport(ag Agent) (HookSupport, bool) {
	return declaredCapability[HookSupport](ag, func(c DeclaredCaps) bool { return c.Hooks })
}

// AsHookFreshness returns the agent as HookFreshness if it implements the
// interface. No capability declaration is needed: hook-config drift detection
// is built-in only, since it compares against a template the CLI itself
// embeds. External agents own their hook config and report installation state
// through their own protocol.
func AsHookFreshness(ag Agent) (HookFreshness, bool) {
	return builtinCapability[HookFreshness](ag)
}

// AsTranscriptAnalyzer returns the agent as TranscriptAnalyzer if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsTranscriptAnalyzer(ag Agent) (TranscriptAnalyzer, bool) {
	return declaredCapability[TranscriptAnalyzer](ag, func(c DeclaredCaps) bool { return c.TranscriptAnalyzer })
}

// AsTranscriptPreparer returns the agent as TranscriptPreparer if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsTranscriptPreparer(ag Agent) (TranscriptPreparer, bool) {
	return declaredCapability[TranscriptPreparer](ag, func(c DeclaredCaps) bool { return c.TranscriptPreparer })
}

// AsTranscriptCapturer returns the agent as TranscriptCapturer if it implements
// the built-in-only Stop capture interface.
func AsTranscriptCapturer(ag Agent) (TranscriptCapturer, bool) {
	return builtinCapability[TranscriptCapturer](ag)
}

// AsTranscriptTurnAnalyzer returns the agent as TranscriptTurnAnalyzer when it
// can derive all turn metadata from a captured transcript in one pass.
func AsTranscriptTurnAnalyzer(ag Agent) (TranscriptTurnAnalyzer, bool) {
	return builtinCapability[TranscriptTurnAnalyzer](ag)
}

// AsRepeatableTurnEnd returns the agent as RepeatableTurnEnd if its hook
// protocol can continue an assistant turn after a turn-end event.
func AsRepeatableTurnEnd(ag Agent) (RepeatableTurnEnd, bool) {
	return builtinCapability[RepeatableTurnEnd](ag)
}

// AsSidecarImageProvider returns the agent as SidecarImageProvider if it
// implements the interface. This is a best-effort, optional capability (image
// capture from a store outside the transcript, e.g. Cursor's SQLite blob store),
// so it resolves by type assertion alone with no DeclaredCaps gate.
func AsSidecarImageProvider(ag Agent) (SidecarImageProvider, bool) {
	if ag == nil {
		return nil, false
	}
	p, ok := ag.(SidecarImageProvider)
	return p, ok
}

// AsTranscriptSanitizer returns the agent as TranscriptSanitizer if it implements
// the interface. This is a pure local byte transform with no external process to
// negotiate with, so it needs no DeclaredCaps gate.
func AsTranscriptSanitizer(ag Agent) (TranscriptSanitizer, bool) {
	return builtinCapability[TranscriptSanitizer](ag)
}

// SanitizeTranscriptForStorage applies the agent's storage sanitizer when it has one
// and returns data unchanged otherwise. Every path that stores a transcript copy
// should call this BEFORE redaction — see TranscriptSanitizer for why. A no-op for
// agents without the capability and idempotent for those with it, so it is safe to
// call on any transcript from any path.
func SanitizeTranscriptForStorage(ag Agent, data []byte) []byte {
	if len(data) == 0 {
		return data
	}
	s, ok := AsTranscriptSanitizer(ag)
	if !ok {
		return data
	}
	sanitized := s.SanitizeTranscriptForStorage(data)
	if sanitized == nil {
		// Defensive: the interface forbids this, but a nil return would silently
		// drop the whole session. Prefer the unsanitized transcript over none.
		return data
	}
	return sanitized
}

// AsTranscriptFetcher returns the agent as TranscriptFetcher if it implements
// the interface. This is an optional capability (materializing a transcript on
// demand for sessions with no hook-cached file), so it resolves by type
// assertion alone with no DeclaredCaps gate.
func AsTranscriptFetcher(ag Agent) (TranscriptFetcher, bool) {
	return builtinCapability[TranscriptFetcher](ag)
}

// AsTokenCalculator returns the agent as TokenCalculator if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsTokenCalculator(ag Agent) (TokenCalculator, bool) {
	return declaredCapability[TokenCalculator](ag, func(c DeclaredCaps) bool { return c.TokenCalculator })
}

// AsTextGenerator returns the agent as TextGenerator if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsTextGenerator(ag Agent) (TextGenerator, bool) {
	return declaredCapability[TextGenerator](ag, func(c DeclaredCaps) bool { return c.TextGenerator })
}

// AsStreamingTextGenerator returns the agent as StreamingTextGenerator if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsStreamingTextGenerator(ag Agent) (StreamingTextGenerator, bool) {
	if ag == nil {
		return nil, false
	}
	stg, ok := ag.(StreamingTextGenerator)
	if !ok {
		return nil, false
	}
	if cd, ok := ag.(CapabilityDeclarer); ok {
		return stg, cd.DeclaredCapabilities().StreamingTextGenerator
	}
	return stg, true
}

// AsTranscriptCompactor returns the agent as TranscriptCompactor if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsTranscriptCompactor(ag Agent) (TranscriptCompactor, bool) {
	return declaredCapability[TranscriptCompactor](ag, func(c DeclaredCaps) bool { return c.CompactTranscript })
}

// AsHookResponseWriter returns the agent as HookResponseWriter if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsHookResponseWriter(ag Agent) (HookResponseWriter, bool) {
	return declaredCapability[HookResponseWriter](ag, func(c DeclaredCaps) bool { return c.HookResponseWriter })
}

// AsPromptExtractor returns the agent as PromptExtractor if it both implements
// the interface and (for CapabilityDeclarer agents) has declared TranscriptAnalyzer.
// ExtractPrompts is conceptually part of transcript analysis, so it shares the same
// capability gate — this prevents calling extract-prompts on external agent binaries
// that never declared transcript_analyzer support.
func AsPromptExtractor(ag Agent) (PromptExtractor, bool) {
	return declaredCapability[PromptExtractor](ag, func(c DeclaredCaps) bool { return c.TranscriptAnalyzer })
}

// AsSubagentAwareExtractor returns the agent as SubagentAwareExtractor if it both
// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
func AsSubagentAwareExtractor(ag Agent) (SubagentAwareExtractor, bool) {
	return declaredCapability[SubagentAwareExtractor](ag, func(c DeclaredCaps) bool { return c.SubagentAwareExtractor })
}

// AsSubagentSessionResolver returns the agent as SubagentSessionResolver if it
// implements the interface. No capability declaration is needed: whether an
// agent's subagents run as sessions of their own is a property of the agent's
// own hook protocol, which only built-in agents model. External agents report
// subagent boundaries through their own hooks.
func AsSubagentSessionResolver(ag Agent) (SubagentSessionResolver, bool) {
	return builtinCapability[SubagentSessionResolver](ag)
}

// AsSessionBaseDirProvider returns the agent as SessionBaseDirProvider if it implements
// the interface. No capability declaration is needed since this is a built-in-only feature
// (external agents use the agent binary's own session resolution).
func AsSessionBaseDirProvider(ag Agent) (SessionBaseDirProvider, bool) {
	return builtinCapability[SessionBaseDirProvider](ag)
}

// AsModelExtractor returns the agent as ModelExtractor if it implements the
// interface. No capability declaration is needed: transcript-based model
// extraction is a built-in-only fallback for agents whose hooks omit the model
// (e.g., Pi). External agents report the model through their own hook protocol.
func AsModelExtractor(ag Agent) (ModelExtractor, bool) {
	return builtinCapability[ModelExtractor](ag)
}

// AsSkillEventExtractor returns the agent as SkillEventExtractor if it implements
// the interface. Skill-event extraction is currently built-in only; external
// agents do not expose this optional interface through declared capabilities.
func AsSkillEventExtractor(ag Agent) (SkillEventExtractor, bool) {
	return builtinCapability[SkillEventExtractor](ag)
// Package agent provides interfaces and types for integrating with coding agents.
// It abstracts agent-specific behavior (hooks, log parsing, session storage) so that
// the same Strategy implementations can work with any coding agent.
package agent

import (
	"context"
	"errors"
	"io"
	"os/exec"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// Agent defines the interface for interacting with a coding agent.
// Each agent implementation (Claude Code, Cursor, Aider, etc.) converts its
// native format to the normalized types defined in this package.
//
// The interface is organized into three groups:
//   - Identity (5 methods): Name, Type, Description, DetectPresence, ProtectedDirs
//   - Transcript Storage (3 methods): ReadTranscript, ChunkTranscript, ReassembleTranscript
//   - Legacy (6 methods): Will be moved to optional interfaces or removed in a future phase
type Agent interface {
	// --- Identity ---

	// Name returns the agent registry key (e.g., "claude-code", "gemini")
	Name() types.AgentName

	// Type returns the agent type identifier (e.g., "Claude Code", "Gemini CLI")
	// This is stored in metadata and trailers.
	Type() types.AgentType

	// Description returns a human-readable description for UI
	Description() string

	// IsPreview returns whether the agent integration is in preview or stable
	IsPreview() bool

	// DetectPresence checks if this agent is configured in the repository
	DetectPresence(ctx context.Context) (bool, error)

	// ProtectedDirs returns repo-root-relative directories that should never be
	// modified or deleted during rewind or other destructive operations.
	// Examples: [".claude"] for Claude, [".gemini"] for Gemini.
	ProtectedDirs() []string

	// --- Transcript Storage ---

	// ReadTranscript reads the raw transcript bytes for a session.
	ReadTranscript(sessionRef string) ([]byte, error)

	// ChunkTranscript splits a transcript into chunks if it exceeds maxSize.
	// Returns a slice of chunks. If the transcript fits in one chunk, returns single-element slice.
	// The chunking is format-aware: JSONL splits at line boundaries, JSON splits message arrays.
	ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error)

	// ReassembleTranscript combines chunks back into a single transcript.
	// Handles format-specific reassembly (JSONL concatenation, JSON message merging).
	ReassembleTranscript(chunks [][]byte) ([]byte, error)

	// --- Legacy methods (will move to optional interfaces in Phase 4) ---

	// GetSessionID extracts session ID from hook input.
	GetSessionID(input *HookInput) string

	// GetSessionDir returns where agent stores session data for this repo.
	GetSessionDir(repoPath string) (string, error)

	// ResolveSessionFile returns the path to the session transcript file.
	//
	// SECURITY CONTRACT: agentSessionID is used to build a filesystem path and
	// some implementations use it as a directory component or (Codex/Pi) return
	// it verbatim when absolute. Callers that source agentSessionID from
	// untrusted data (e.g. checkpoint metadata on the shared
	// entire/checkpoints/v1 branch, hook input) MUST validate it with
	// validation.ValidateSessionID first. The resume/rewind restore paths do
	// this at their choke points (transcript.resolveTranscriptPath and
	// strategy.RestoreLogsOnly); do not call this with unvalidated input.
	ResolveSessionFile(sessionDir, agentSessionID string) string

	// ReadSession reads session data from agent's storage.
	ReadSession(input *HookInput) (*AgentSession, error)

	// WriteSession writes session data for resumption.
	WriteSession(ctx context.Context, session *AgentSession) error

	// FormatResumeCommand returns command to resume a session.
	FormatResumeCommand(sessionID string) string
}

// HookSupport is implemented by agents with lifecycle hooks.
// This optional interface allows agents like Claude Code and Cursor to
// install and manage hooks that notify Entire of agent events.
//
// The interface is organized into two groups:
//   - Hook Mapping (2 methods): HookNames, ParseHookEvent
//   - Hook Management (3 methods): InstallHooks, UninstallHooks, AreHooksInstalled
type HookSupport interface {
	Agent

	// HookNames returns the hook verbs this agent supports.
	// These become subcommands under `entire hooks <agent>`.
	// e.g., ["stop", "user-prompt-submit", "session-start", "session-end"]
	HookNames() []string

	// ParseHookEvent translates an agent-native hook into a normalized lifecycle Event.
	// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
	// This is the core contribution surface for new agent implementations.
	ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*Event, error)

	// InstallHooks installs agent-specific hooks.
	// If force is true, removes existing Entire hooks before installing.
	// Returns the number of hooks installed.
	//
	// Installed hook commands must always name the "entire" binary, never a
	// path derived from repository content. Implementations recognize the
	// legacy local-dev command shapes (see LegacyLocalDevHookScript) only so
	// they can replace them.
	InstallHooks(ctx context.Context, force bool) (int, error)

	// UninstallHooks removes installed hooks
	UninstallHooks(ctx context.Context) error

	// AreHooksInstalled checks if hooks are currently installed
	AreHooksInstalled(ctx context.Context) bool
}

// HookConfigState describes how an agent's installed Entire hook config
// compares to what InstallHooks would write today.
type HookConfigState int

const (
	// HooksAbsent means Entire hooks are not installed for this agent here.
	HooksAbsent HookConfigState = iota
	// HooksCurrent means the installed hooks match what would be written today.
	HooksCurrent
	// HooksOutdated means Entire hooks are installed but stale — an older CLI
	// wrote a config that no longer matches the current one. Fix:
	// `entire enable --force`.
	HooksOutdated
)

// HookFreshness is implemented by hook-supporting agents that can report
// whether their installed config has drifted from the current one.
//
// AreHooksInstalled answers "is Entire wired up here at all?" — for agents
// whose hook config is a generated file checked into the repo, that stays true
// forever even after the generated content goes stale, because the file is
// still present and still recognisably Entire's. CheckHookConfig answers the
// separate question "is what's installed still what we'd write today?", so
// `entire status` and `entire doctor` can flag a stale config instead of
// reporting it healthy while its hooks silently no-op.
//
// Implementations must be read-only: they are diagnostics and must never
// modify the agent's config.
type HookFreshness interface {
	Agent

	// CheckHookConfig reports whether this agent's Entire hook config is
	// absent, current, or outdated in the current repo.
	CheckHookConfig(ctx context.Context) HookConfigState
}

// FileWatcher is implemented by agents that use file-based detection.
// Agents like Aider that don't support hooks can use file watching
// to detect session activity.
type FileWatcher interface {
	Agent

	// GetWatchPaths returns paths to watch for session changes
	GetWatchPaths() ([]string, error)

	// OnFileChange handles a detected file change and returns session info
	OnFileChange(path string) (*SessionChange, error)
}

// ProtectedFilesProvider is implemented by agents that need to exclude
// repo-root-relative files owned by the agent integration itself from session
// tracking or destructive operations.
type ProtectedFilesProvider interface {
	Agent

	// ProtectedFiles returns repo-root-relative files that belong to the
	// agent's own config/state and should be excluded from tracking.
	ProtectedFiles() []string
}

// TranscriptAnalyzer provides format-specific transcript parsing.
// Agents that implement this get richer checkpoints (transcript-derived file lists,
// prompts, summaries). Agents that don't still participate in the checkpoint lifecycle
// via git-status-based file detection and raw transcript storage.
type TranscriptAnalyzer interface {
	Agent

	// GetTranscriptPosition returns the current position (length) of a transcript.
	// For JSONL formats (Claude Code), this is the line count.
	// For JSON formats (Gemini CLI), this is the message count.
	// Returns 0 if the file doesn't exist or is empty.
	GetTranscriptPosition(path string) (int, error)

	// ExtractModifiedFilesFromOffset extracts files modified since a given offset.
	// For JSONL formats (Claude Code), offset is the starting line number.
	// For JSON formats (Gemini CLI), offset is the starting message index.
	// Returns:
	//   - files: list of file paths modified by the agent (from Write/Edit tools)
	//   - currentPosition: the current position (line count or message count)
	//   - error: any error encountered during reading
	ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error)
}

// PromptExtractor extracts user prompts from a transcript file.
// Used as a fallback when prompt data isn't captured via hooks (e.g., Factory AI
// Droid's exec mode doesn't fire UserPromptSubmit).
type PromptExtractor interface {
	Agent

	// ExtractPrompts returns user prompts from the transcript starting at the given offset.
	ExtractPrompts(sessionRef string, fromOffset int) ([]string, error)
}

// TranscriptPreparer is called before ReadTranscript to handle agent-specific
// materialization or flush requirements. Stop handlers prefer TranscriptCapturer
// when available so readiness and reading stay atomic.
type TranscriptPreparer interface {
	Agent

	// PrepareTranscript ensures the transcript is ready to read.
	// For Claude Code, this waits for the async transcript flush to complete.
	PrepareTranscript(ctx context.Context, sessionRef string) error
}

// ErrTranscriptNotReady means no transcript snapshot was safe to consume.
var ErrTranscriptNotReady = errors.New("transcript not ready")

// TranscriptCaptureRequest describes the turn boundary and producer evidence
// needed to capture a ready transcript snapshot.
type TranscriptCaptureRequest struct {
	SessionRef    string
	StartPosition int
	FinalResponse *string
}

// TranscriptSnapshot is an Entire-owned, read-only copy of validated transcript
// bytes. Position is derived from Data, never from a later source-path read.
type TranscriptSnapshot struct {
	Data     []byte
	Position int
}

// TranscriptCapturer combines transcript readiness validation with the read
// whose bytes lifecycle consumers will use.
type TranscriptCapturer interface {
	Agent

	CaptureTranscript(ctx context.Context, request TranscriptCaptureRequest) (TranscriptSnapshot, error)
}

