}

// TranscriptSanitizer is implemented by agents whose native transcript format
// carries state that Entire must not keep in its own copy — e.g. Codex rollouts
// embed encrypted reasoning payloads and compaction blobs that are bound to the
// originating session and cannot be replayed out of a checkpoint.
//
// Entire always leaves the agent's own transcript untouched; this transform applies
// only to the copy Entire stores. Sanitizing before redaction is what keeps
// non-replayable payloads out of storage AND keeps the redaction layers from
// scanning megabytes of ciphertext they would only discard afterwards (base64 is
// the pathological input for the entropy layer).
//
// Implementations must be pure byte transforms: idempotent (sanitizing an
// already-sanitized transcript is a no-op), safe to call from hooks, and never
// dependent on the agent process being alive.
type TranscriptSanitizer interface {
	Agent

	// SanitizeTranscriptForStorage returns the transcript with non-portable state
	// removed. It must return the input unchanged rather than nil when it cannot
	// parse the transcript, so a sanitizer failure never loses the session.
	SanitizeTranscriptForStorage(data []byte) []byte
}

// TokenCalculator provides token usage calculation for a session.
// The framework calls this during step save and checkpoint if implemented.
type TokenCalculator interface {
	Agent

	// CalculateTokenUsage computes token usage from the transcript starting at the given offset.
	CalculateTokenUsage(transcriptData []byte, fromOffset int) (*TokenUsage, error)
}

// ModelExtractor extracts the LLM model identifier from a transcript for agents
// that do not report the model through lifecycle hooks. Pi, for example, records
// the model on every assistant message (message.model) but its hook events carry
// no model field, so the transcript is the only source. The framework calls this
// during condensation to backfill session state when the model is otherwise
// unknown.
type ModelExtractor interface {
	Agent

	// ExtractModel returns the model identifier from the transcript (e.g.
	// "gpt-5.5"), or "" if none can be determined.
	ExtractModel(transcriptData []byte) (string, error)
}

// TextGenerator is an optional interface for agents whose CLI supports
// non-interactive text generation (e.g., claude --print).
// Used for AI-powered metadata generation (trail titles, summaries).
type TextGenerator interface {
	Agent

	// GenerateText sends a prompt to the agent's CLI and returns the raw text response.
	// model is a hint (e.g., "haiku", "sonnet"). Implementations may ignore if not applicable.
	GenerateText(ctx context.Context, prompt string, model string) (string, error)
}

// ProgressPhase identifies a coarse stage in streaming text generation.
type ProgressPhase string

const (
	// PhaseConnecting is emitted once when the CLI signals it is making the upstream request.
	PhaseConnecting ProgressPhase = "connecting"
	// PhaseFirstToken is emitted once when the upstream responds with the first event,
	// carrying TTFT and input/cache token counts.
	PhaseFirstToken ProgressPhase = "first-token"
	// PhaseGenerating is emitted repeatedly as text or thinking deltas arrive.
	// OutputTokens carries a running estimate based on delta sizes.
	PhaseGenerating ProgressPhase = "generating"
	// PhaseDone is emitted once when the final result event is received without error.
	PhaseDone ProgressPhase = "done"
)

// GenerationProgress reports a snapshot of streaming text generation progress.
// Fields not relevant to the current Phase may be zero-valued.
type GenerationProgress struct {
	Phase             ProgressPhase
	OutputTokens      int // running estimate during PhaseGenerating; final at PhaseDone
	InputTokens       int // populated at PhaseFirstToken
	CachedInputTokens int // populated at PhaseFirstToken
	TTFTms            int // time-to-first-token, populated at PhaseFirstToken
	DurationMs        int // populated at PhaseDone (final result event)
}

// ProgressFn receives streaming progress updates. It must not block — invoke it
// from the same goroutine that reads the stream and keep handlers fast.
type ProgressFn func(GenerationProgress)

// StreamingTextGenerator is an optional interface for text generators whose
// underlying CLI exposes a streaming output mode. Callers can use AsStreamingTextGenerator
// to detect support and fall back to plain GenerateText when unavailable.
type StreamingTextGenerator interface {
	Agent

	// GenerateTextStreaming invokes the agent's streaming text generation and
	// calls progress for each phase update. progress may be nil to suppress
	// reporting. The returned string is the final response text.
	GenerateTextStreaming(ctx context.Context, prompt, model string, progress ProgressFn) (string, error)
}

// CompactedTranscript contains the result of transcript compaction into Entire
// Transcript Format. Assets are accepted in the protocol shape for forward
// compatibility but may not yet be persisted by all call sites.
type CompactedTranscript struct {
	Transcript []byte
	Assets     []CompactedTranscriptAsset
}

// CompactedTranscriptAsset is binary data extracted during transcript compaction.
type CompactedTranscriptAsset struct {
	Name      string
	MediaType string
	Data      []byte
}

// TranscriptCompactor is implemented by agents that can produce Entire
// Transcript Format directly from their native transcript representation.
type TranscriptCompactor interface {
	Agent

	// CompactTranscript converts the transcript referenced by sessionRef into
	// Entire Transcript Format and returns the compact transcript bytes.
	CompactTranscript(ctx context.Context, sessionRef string) (*CompactedTranscript, error)
}

// HookResponseWriter is implemented by agents that support structured hook responses.
// Agents that implement this can output messages (e.g., banners) to the user via
// the agent's response protocol. For example, Claude Code outputs JSON with a
// systemMessage field to stdout. Agents that don't implement this will silently
// skip hook response output.
type HookResponseWriter interface {
	Agent

	// WriteHookResponse outputs a message to the user via the agent's hook response protocol.
	WriteHookResponse(message string) error
}

// SessionEndBudgeter is implemented by agents whose host enforces a hard
// wall-clock budget on the session-end hook, because it runs inside the agent's
// own shutdown sequence rather than between turns.
//
// Codex is the motivating case: it defaults SessionEnd handlers to a 1s timeout
// and clamps any configured value to 3s (SESSION_END_MAX_TIMEOUT_SEC in
// codex-rs/hooks/src/events/session_end.rs), keeping teardown inside
// app-server's five-second shutdown bound. On expiry it terminates the hook's
// entire process tree.
//
// Declaring a budget makes Entire stop itself just short of that ceiling rather
// than being killed mid-write: the session is marked ENDED first (a single
// atomic state-file rename), and only the eager condense — which is fail-open
// — runs against the remaining budget. PostCommit handles sessions with pending
// files; doctor retries no-file ENDED sessions. Agents whose session-end hook
// has a normal timeout should not implement this.
type SessionEndBudgeter interface {
	Agent

	// SessionEndBudget returns the wall-clock budget for the whole session-end
	// hook invocation, measured from process start. A non-positive value means
	// no budget applies.
	SessionEndBudget() time.Duration
package claudecode

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

type captureConfig struct {
	pollInterval   time.Duration
	quietWindow    time.Duration
	maxWait        time.Duration
	staleThreshold time.Duration
	readTranscript func(context.Context, string, transcriptFingerprint) ([]byte, error)
}

const (
	defaultPollInterval           = 50 * time.Millisecond
	defaultQuietWindow            = 500 * time.Millisecond
	defaultMaxWait                = 3 * time.Second
	defaultStaleThreshold         = 2 * time.Minute
	assistantContentBlockTypeText = "text"
)

var assistantRecordMarker = []byte(envelopeTypeAssistant)

func defaultCaptureConfig() captureConfig {
	return captureConfig{
		pollInterval:   defaultPollInterval,
		quietWindow:    defaultQuietWindow,
		maxWait:        defaultMaxWait,
		staleThreshold: defaultStaleThreshold,
	}
}

type transcriptFingerprint struct {
	info    os.FileInfo
	size    int64
	modTime time.Time
}

var errTranscriptChanged = errors.New("transcript changed during capture")

func (c *ClaudeCodeAgent) CaptureTranscript(ctx context.Context, request agent.TranscriptCaptureRequest) (agent.TranscriptSnapshot, error) {
	return c.captureTranscript(ctx, request, defaultCaptureConfig())
}

func (c *ClaudeCodeAgent) captureTranscript(
	ctx context.Context,
	request agent.TranscriptCaptureRequest,
	config captureConfig,
) (agent.TranscriptSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return agent.TranscriptSnapshot{}, fmt.Errorf("capture transcript canceled: %w", err)
	}
	if request.StartPosition < 0 {
		return agent.TranscriptSnapshot{}, fmt.Errorf("%w: negative turn-start position", agent.ErrTranscriptNotReady)
	}
	captureCtx, cancel := context.WithTimeout(ctx, config.maxWait)
	defer cancel()

	observed, err := fingerprintTranscript(request.SessionRef)
	if err != nil {
		return agent.TranscriptSnapshot{}, fmt.Errorf("%w: %w", agent.ErrTranscriptNotReady, err)
	}
	if err := captureCtx.Err(); err != nil {
		return agent.TranscriptSnapshot{}, captureWaitError(ctx, config.maxWait)
	}
	if time.Since(observed.modTime) > config.staleThreshold {
		return agent.TranscriptSnapshot{}, fmt.Errorf("%w: transcript is stale", agent.ErrTranscriptNotReady)
	}
	modern := request.FinalResponse != nil && *request.FinalResponse != ""

	ticker := time.NewTicker(config.pollInterval)
	defer ticker.Stop()
	// Producer evidence can validate the initial snapshot immediately. The
	// legacy path still waits for quietWindow before it can return.
	immediate := make(chan time.Time, 1)
	immediate <- time.Now()
	poll := (<-chan time.Time)(immediate)
	readTranscript := config.readTranscript
	if readTranscript == nil {
		readTranscript = readObservedTranscript
	}
	stableSince := time.Now()
	observedValid := true
	var rejected transcriptFingerprint
	hasRejected := false

	for {
		select {
		case <-captureCtx.Done():
			return agent.TranscriptSnapshot{}, captureWaitError(ctx, config.maxWait)
		case <-poll:
			poll = ticker.C
			current, statErr := fingerprintTranscript(request.SessionRef)
			if statErr != nil {
				observedValid = false
				stableSince = time.Now()
				continue
			}
			if time.Since(current.modTime) > config.staleThreshold {
				observedValid = false
				stableSince = time.Now()
				continue
			}
			if !observedValid || !sameTranscriptFingerprint(observed, current) {
				observed = current
				observedValid = true
				stableSince = time.Now()
			}
			if !modern {
				if time.Since(stableSince) < config.quietWindow {
					continue
				}
			}
			if hasRejected && sameTranscriptFingerprint(rejected, current) {
				continue
			}

			data, readErr := readTranscript(captureCtx, request.SessionRef, current)
			if readErr != nil {
				if ctxErr := ctx.Err(); ctxErr != nil {
					return agent.TranscriptSnapshot{}, fmt.Errorf("capture transcript canceled: %w", ctxErr)
				}
				if captureCtx.Err() != nil {
					return agent.TranscriptSnapshot{}, captureWaitError(ctx, config.maxWait)
				}
				if errors.Is(readErr, errTranscriptChanged) {
					observedValid = false
					if refreshed, refreshErr := fingerprintTranscript(request.SessionRef); refreshErr == nil {
						observed = refreshed
						observedValid = true
						stableSince = time.Now()
					}
					continue
				}
				return agent.TranscriptSnapshot{}, fmt.Errorf("%w: %w", agent.ErrTranscriptNotReady, readErr)
			}

			position, finalAssistant, validationErr := validateTranscriptSnapshot(captureCtx, data, request.StartPosition, modern)
			if validationErr != nil {
				if captureCtx.Err() != nil {
					return agent.TranscriptSnapshot{}, captureWaitError(ctx, config.maxWait)
				}
				rejected = current
				hasRejected = true
				continue
			}
			if request.FinalResponse != nil && *request.FinalResponse != "" && finalAssistant != *request.FinalResponse {
				rejected = current
				hasRejected = true
				continue
			}
			if captureCtx.Err() != nil {
				return agent.TranscriptSnapshot{}, captureWaitError(ctx, config.maxWait)
			}
			return agent.TranscriptSnapshot{Data: data, Position: position}, nil
		}
	}
}

func captureWaitError(ctx context.Context, maxWait time.Duration) error {
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("capture transcript canceled: %w", err)
	}
	return fmt.Errorf("%w: timed out after %s", agent.ErrTranscriptNotReady, maxWait)
}

func fingerprintTranscript(path string) (transcriptFingerprint, error) {
	info, err := os.Stat(path)
	if err != nil {
		return transcriptFingerprint{}, fmt.Errorf("stat transcript: %w", err)
	}
	if !info.Mode().IsRegular() {
		return transcriptFingerprint{}, errors.New("not a regular file")
	}
	return transcriptFingerprint{info: info, size: info.Size(), modTime: info.ModTime()}, nil
}

func sameTranscriptFingerprint(left, right transcriptFingerprint) bool {
	return os.SameFile(left.info, right.info) && left.size == right.size && left.modTime.Equal(right.modTime)
}

func readObservedTranscript(ctx context.Context, path string, observed transcriptFingerprint) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("capture transcript canceled: %w", err)
	}
	f, err := os.Open(path) //nolint:gosec // path comes from the agent hook payload
	if err != nil {
		return nil, fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	before, err := f.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat opened transcript: %w", err)
	}
	opened := transcriptFingerprint{info: before, size: before.Size(), modTime: before.ModTime()}
	if !sameTranscriptFingerprint(observed, opened) {
		return nil, errTranscriptChanged
	}

	data := make([]byte, observed.size)
	if _, err := io.ReadFull(f, data); err != nil {
		return nil, fmt.Errorf("%w: %w", errTranscriptChanged, err)
	}
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("capture transcript canceled: %w", err)
	}

	after, err := f.Stat()
	if err != nil {
		return nil, fmt.Errorf("restat opened transcript: %w", err)
	}
	pathAfter, err := fingerprintTranscript(path)
	if err != nil {
		return nil, errTranscriptChanged
	}
	handleAfter := transcriptFingerprint{info: after, size: after.Size(), modTime: after.ModTime()}
	if !sameTranscriptFingerprint(observed, handleAfter) || !sameTranscriptFingerprint(observed, pathAfter) {
		return nil, errTranscriptChanged
	}
	return data, nil
}

func validateTranscriptSnapshot(ctx context.Context, data []byte, startPosition int, reconstructAssistant bool) (int, string, error) {
	position := 0
	latestAssistant := ""
	var finalRecord []byte
	remaining := data
	for len(remaining) > 0 {
		if err := ctx.Err(); err != nil {
			return 0, "", fmt.Errorf("validate transcript canceled: %w", err)
		}
		line := remaining
		if newline := bytes.IndexByte(remaining, '\n'); newline >= 0 {
			line = remaining[:newline]
			remaining = remaining[newline+1:]
		} else {
			remaining = nil
		}

		linePosition := position
		position++
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			continue
		}
		finalRecord = trimmed
		if reconstructAssistant && linePosition >= startPosition {
			if !json.Valid(trimmed) {
				return 0, "", errors.New("parse transcript record: invalid JSON")
			}
			// Claude's transcript is producer-owned compact JSONL. Most records are
			// user/tool metadata; avoid allocating an envelope for records that cannot
			// contain the assistant type value.
			if bytes.Contains(trimmed, assistantRecordMarker) {
				var envelope struct {
					Type    string          `json:"type"`
					Message json.RawMessage `json:"message"`
				}
				if err := json.Unmarshal(trimmed, &envelope); err != nil {
					return 0, "", fmt.Errorf("parse transcript record: %w", err)
				}
				if envelope.Type == envelopeTypeAssistant {
					if text := assistantText(envelope.Message); strings.TrimSpace(text) != "" {
						latestAssistant = text
					}
				}
			}
		}
	}

	if len(finalRecord) == 0 {
		return 0, "", errors.New("transcript has no JSONL records")
	}
	if !json.Valid(finalRecord) {
		return 0, "", errors.New("parse final transcript record: invalid JSON")
	}
	if err := ctx.Err(); err != nil {
		return 0, "", fmt.Errorf("validate transcript canceled: %w", err)
	}
	return position, latestAssistant, nil
}

func assistantText(message json.RawMessage) string {
	var parsed struct {
		Content json.RawMessage `json:"content"`
	}
	if json.Unmarshal(message, &parsed) != nil {
		return ""
	}

	var text string
	if json.Unmarshal(parsed.Content, &text) == nil {
		return strings.TrimSpace(text)
	}
	var blocks []struct {
		Type string `json:"type"`
		Text string `json:"text"`
	}
	if json.Unmarshal(parsed.Content, &blocks) != nil {
		return ""
	}
	var textBlocks []string
	for _, block := range blocks {
		if block.Type == assistantContentBlockTypeText {
			textBlocks = append(textBlocks, block.Text)
		}
	}
	return strings.TrimSpace(strings.Join(textBlocks, "\n"))
}
package claudecode

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// TranscriptLine is an alias to the shared transcript.Line type.
type TranscriptLine = transcript.Line

// Type aliases for internal use.
type (
	assistantMessage = transcript.AssistantMessage
	toolInput        = transcript.ToolInput
)

// SerializeTranscript converts transcript lines back to JSONL bytes
func SerializeTranscript(lines []TranscriptLine) ([]byte, error) {
	var buf bytes.Buffer
	for _, line := range lines {
		data, err := json.Marshal(line)
		if err != nil {
			return nil, fmt.Errorf("failed to marshal line: %w", err)
		}
		buf.Write(data)
		buf.WriteByte('\n')
	}
	return buf.Bytes(), nil
}

// ExtractModifiedFiles extracts files modified by tool calls from transcript
func ExtractModifiedFiles(lines []TranscriptLine) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range lines {
		if line.Type != envelopeTypeAssistant {
			continue
		}

		var msg assistantMessage
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type != "tool_use" {
				continue
			}

			// Check if it's a file modification tool
			isModifyTool := false
			for _, name := range FileModificationTools {
				if block.Name == name {
					isModifyTool = true
					break
				}
			}

			if !isModifyTool {
				continue
			}

			var input toolInput
			if err := json.Unmarshal(block.Input, &input); err != nil {
				continue
			}

			file := input.FilePath
			if file == "" {
				file = input.NotebookPath
			}

			if file != "" && !fileSet[file] {
				fileSet[file] = true
				files = append(files, file)
			}
		}
	}

	return files
}

// TruncateAtUUID returns transcript lines up to and including the line with given UUID
func TruncateAtUUID(lines []TranscriptLine, uuid string) []TranscriptLine {
	if uuid == "" {
		return lines
	}

	for i, line := range lines {
		if line.UUID == uuid {
			return lines[:i+1]
		}
	}

	// UUID not found, return full transcript
	return lines
}

// toolResultBlock represents a tool_result in a user message
type toolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
}

// userMessageWithToolResults represents a user message that may contain tool results
type userMessageWithToolResults struct {
	Content []toolResultBlock `json:"content"`
}

// FindCheckpointUUID finds the UUID of the message containing the tool_result
// for the given tool_use_id
func FindCheckpointUUID(lines []TranscriptLine, toolUseID string) (string, bool) {
	for _, line := range lines {
		if line.Type != "user" {
			continue
		}

		var msg userMessageWithToolResults
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
				return line.UUID, true
			}
		}
	}
	return "", false
}

// CalculateTokenUsage calculates token usage from a Claude Code transcript.
// This is specific to Claude/Anthropic's API format where each assistant message
// contains a usage object with input_tokens, output_tokens, and cache tokens.
//
// Due to streaming, multiple transcript rows may share the same message.id.
// We deduplicate by taking the row with the highest output_tokens for each message.id.
func CalculateTokenUsage(transcript []TranscriptLine) *agent.TokenUsage {
	// Map from message.id to the usage with highest output_tokens
	usageByMessageID := make(map[string]messageUsage)

	for _, line := range transcript {
		if line.Type != envelopeTypeAssistant {
			continue
		}

		var msg messageWithUsage
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		if msg.ID == "" {
			continue
		}

		// Keep the entry with highest output_tokens (final streaming state)
		existing, exists := usageByMessageID[msg.ID]
		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
			usageByMessageID[msg.ID] = msg.Usage
		}
	}

	// Sum up all unique messages
	usage := &agent.TokenUsage{
		APICallCount: len(usageByMessageID),
	}
	for _, u := range usageByMessageID {
		usage.InputTokens += u.InputTokens
		usage.CacheCreationTokens += u.CacheCreationInputTokens
		usage.CacheReadTokens += u.CacheReadInputTokens
		usage.OutputTokens += u.OutputTokens
	}

	return usage
}

// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
// If startLine > 0, only considers lines from startLine onwards.
func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
	if path == "" {
		return &agent.TokenUsage{}, nil
	}

	lines, err := transcript.ParseFromFileAtLine(path, startLine)
	if err != nil {
		return nil, err //nolint:wrapcheck // caller adds context
	}

	return CalculateTokenUsage(lines), nil
}

// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
// Returns a map of agentID -> toolUseID for all spawned agents.
func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
	agentIDs := make(map[string]string)

	for _, line := range transcript {
		if line.Type != "user" {
			continue
		}

		// Parse as array of content blocks (tool results)
		var contentBlocks []struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Content   json.RawMessage `json:"content"`
		}

		var msg struct {
			Content json.RawMessage `json:"content"`
			Content json.RawMessage `json:"content"`
		}
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
			continue
		}

		for _, block := range contentBlocks {
			if block.Type != "tool_result" {
				continue
			}

			// Content can be a string or array of text blocks
			var textContent string

			// Try as array of text blocks first
			var textBlocks []struct {
				Type string `json:"type"`
				Text string `json:"text"`
			}
			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
				var textContentSb361 strings.Builder
				for _, tb := range textBlocks {
					if tb.Type == "text" {
						textContentSb361.WriteString(tb.Text + "\n")
					}
				}
				textContent += textContentSb361.String()
			} else {
				// Try as plain string
				var str string
				if err := json.Unmarshal(block.Content, &str); err == nil {
					textContent = str
				}
			}

			// Look for agentId in the text. Drop any ID that isn't path-safe:
			// callers build agent-<id>.jsonl from it and read that file, so this
			// is the choke point that keeps the path inside subagentsDir,
			// independent of extractAgentIDFromText's character handling.
			if agentID := extractAgentIDFromText(textContent); agentID != "" && validation.ValidateAgentID(agentID) == nil {
				agentIDs[agentID] = block.ToolUseID
			}
		}
	}

	return agentIDs
}

// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
func extractAgentIDFromText(text string) string {
	const prefix = "agentId: "
	idx := strings.Index(text, prefix)
	if idx == -1 {
		return ""
	}

	// Extract the ID (alphanumeric characters after the prefix)
	start := idx + len(prefix)
	end := start
	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
		text[end] >= 'A' && text[end] <= 'Z' ||
		text[end] >= '0' && text[end] <= '9') {
		end++
	}

	if end > start {
		return text[start:end]
	}
	return ""
}

// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
// It parses the main transcript bytes from startLine, extracts spawned agent IDs,
// and calculates their token usage from transcript files in subagentsDir.
func (c *ClaudeCodeAgent) ExtractSkillEvents(transcriptData []byte, startLine int) ([]agent.SkillEvent, error) {
	if len(transcriptData) == 0 {
		return nil, nil
	}

	sliced := transcript.SliceFromLine(transcriptData, startLine)
	parsed, err := transcript.ParseFromBytes(sliced)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	var events []agent.SkillEvent
	for i, line := range parsed {
		if line.Type != envelopeTypeAssistant {
			continue
		}

		var msg assistantMessage
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
				continue
			}
			var input toolInput
			if err := json.Unmarshal(block.Input, &input); err != nil {
				continue
			}
			skillName := strings.TrimSpace(input.Skill)
			if skillName == "" {
				continue
			}

			native := map[string]string{"tool_name": "Skill"}
			if block.ID != "" {
				native["tool_use_id"] = block.ID
			}
			events = append(events, agent.SkillEvent{
				ID:        claudeSkillEventID(block.ID, startLine+i),
				EventType: agent.SkillEventTypeToolInvocation,
				Skill: agent.SkillEventSkill{
					Name: skillName,
				},
				Source: agent.SkillEventSource{
					Agent:      string(agent.AgentNameClaudeCode),
					Signal:     agent.SkillSignalClaudeSkillToolUse,
					Confidence: agent.SkillConfidenceExplicit,
				},
				TranscriptAnchor: &agent.SkillEventTranscriptAnchor{
					Unit:      "line",
					Start:     startLine + i,
					End:       startLine + i + 1,
					EntryIDs:  nonEmptyStrings(line.UUID),
					ToolUseID: block.ID,
				},
				Native: native,
				Collapse: agent.SkillEventCollapse{
					Target:           agent.SkillCollapseTargetToolPair,
					Label:            "Skill: " + skillName,
					DefaultCollapsed: true,
				},
			})
		}
	}
	return events, nil
}

func claudeSkillEventID(toolUseID string, line int) string {
	if toolUseID != "" {
		return "claude-skill-" + toolUseID
	}
	return fmt.Sprintf("claude-skill-line-%d", line)
}

func nonEmptyStrings(values ...string) []string {
	var out []string
	for _, value := range values {
		if value != "" {
			out = append(out, value)
		}
	}
	return out
}

func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
	analysis, err := c.AnalyzeTranscriptTurn(transcriptData, startLine, subagentsDir)
	if err != nil {
		return nil, err
	}
	return analysis.TokenUsage, nil
}

// ExtractAllModifiedFiles extracts files modified by both the main agent and
// any subagents spawned via the Task tool. It parses the main transcript bytes from
// startLine, collects modified files from the main agent, then reads each
// subagent's transcript from subagentsDir to collect their modified files too.
// The result is a deduplicated list of all modified file paths.
func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
	analysis, err := c.AnalyzeTranscriptTurn(transcriptData, startLine, subagentsDir)
	if err != nil {
		return nil, err
	}
	return analysis.ModifiedFiles, nil
}

// AnalyzeTranscriptTurn parses the main turn once for both file and token
// metadata, then parses each transcript already scoped under this session's
// subagents directory once. Directory membership is stronger and cheaper than
// rediscovering the same agent IDs by reparsing the full main transcript.
func (c *ClaudeCodeAgent) AnalyzeTranscriptTurn(transcriptData []byte, startLine int, subagentsDir string) (*agent.TranscriptAnalysis, error) {
	if len(transcriptData) == 0 {
		return &agent.TranscriptAnalysis{TokenUsage: &agent.TokenUsage{}}, nil
	}

	sliced := transcript.SliceFromLine(transcriptData, startLine)
	parsed, err := transcript.ParseFromBytes(sliced)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	fileSet := make(map[string]bool)
	var files []string
	files = appendUniqueFiles(files, fileSet, ExtractModifiedFiles(parsed))
	mainUsage := CalculateTokenUsage(parsed)
	subagentUsage := &agent.TokenUsage{}
	for _, agentPath := range subagentTranscriptPaths(subagentsDir) {
		agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
		if agentErr != nil {
			continue
		}
		files = appendUniqueFiles(files, fileSet, ExtractModifiedFiles(agentLines))
		agentUsage := CalculateTokenUsage(agentLines)
		subagentUsage.InputTokens += agentUsage.InputTokens
		subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
		subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
		subagentUsage.OutputTokens += agentUsage.OutputTokens
		subagentUsage.APICallCount += agentUsage.APICallCount
	}
	if subagentUsage.APICallCount > 0 {
		mainUsage.SubagentTokens = subagentUsage
	}

	return &agent.TranscriptAnalysis{ModifiedFiles: files, TokenUsage: mainUsage}, nil
}

func appendUniqueFiles(files []string, seen map[string]bool, candidates []string) []string {
	for _, file := range candidates {
		if !seen[file] {
			seen[file] = true
			files = append(files, file)
		}
	}
	return files
}

func subagentTranscriptPaths(dir string) []string {
	if dir == "" {
		return nil
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	paths := make([]string, 0, len(entries))
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasPrefix(name, "agent-") || !strings.HasSuffix(name, ".jsonl") {
			continue
		}
		paths = append(paths, filepath.Join(dir, name))
	}
	return paths
}

