	// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
	// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
	// there genuinely were no prompts. We track whether backfill occurred so we can
	// update session state after SaveStep (which may reinitialize state).
	var backfilledPrompt string
	promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
	existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
	if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
		logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
			slog.String("error", readPromptErr.Error()))
	} else if len(existingPrompt) == 0 {
		if extractor, ok := agent.AsPromptExtractor(ag); ok {
			// A captured Stop cannot use a path-only extractor: reopening the
			// producer-owned file would discard the capture guarantee. Claude
			// records prompt.txt at TurnStart, so it does not need this fallback.
			if capturedTranscript == nil {
				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
				if extractErr != nil {
					logging.Warn(logCtx, "failed to extract prompts from transcript",
						slog.String("error", extractErr.Error()))
				} else if len(prompts) > 0 {
					content := strings.Join(prompts, "\n\n---\n\n")
					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
							slog.String("error", writeErr.Error()))
					} else {
						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
							slog.Int("prompt_count", len(prompts)))
						backfilledPrompt = prompts[len(prompts)-1]
					}
				}
			}
		}
	}

	// The source path remains authoritative for locating separate subagent files;
	// those bytes are outside the captured main transcript.
	subagentsDir := paths.SubagentsDir(filepath.Dir(transcriptRef), event.SessionID)

	// Extract metadata via agent interface (modified files)
	var modifiedFiles []string
	var analyzedTokenUsage *agent.TokenUsage

	if turnAnalyzer, ok := agent.AsTranscriptTurnAnalyzer(ag); ok && capturedTranscript != nil {
		analysis, analysisErr := turnAnalyzer.AnalyzeTranscriptTurn(transcriptData, transcriptOffset, subagentsDir)
		if analysisErr != nil {
			logging.Warn(logCtx, "failed to analyze captured transcript",
				slog.String("error", analysisErr.Error()))
		} else {
			modifiedFiles = analysis.ModifiedFiles
			analyzedTokenUsage = analysis.TokenUsage
		}
	} else if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
		if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
				logging.Warn(logCtx, "failed to extract modified files (with subagents)",
					slog.String("error", fileErr.Error()))
			} else {
				modifiedFiles = files
			}
		} else if capturedTranscript == nil {
			// Path-only analysis remains available to non-capturing agents. A
			// captured Stop may use only the byte-based analyzer above.
			// Fall back to basic extraction (main transcript only)
			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
				logging.Warn(logCtx, "failed to extract modified files",
					slog.String("error", fileErr.Error()))
			} else {
				modifiedFiles = files
			}
		}
	}
	extractSpan.End()

	// Generate commit message from last prompt (read from session state, set at TurnStart).
	// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
	// Fall back to backfilledPrompt extracted from the transcript.
	// Single load serves both prompt retrieval and backfill.
	_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
	lastPrompt := ""
	if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
		lastPrompt = sessionState.LastPrompt
	}
	// Backfill LastPrompt so `entire status` shows the prompt even when no
	// files were modified (before the early return below).
	if lastPrompt == "" && backfilledPrompt != "" {
		lastPrompt = backfilledPrompt
		mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
			if state.LastPrompt != "" {
				return strategy.ErrMutationSkip
			}
			state.LastPrompt = backfilledPrompt
			return nil
		})
		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
			logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
				slog.String("error", mutErr.Error()))
		}
	}
	commitMessage := generateCommitMessage(lastPrompt, ag.Type())
	logging.Debug(logCtx, "using commit message",
		slog.Int("message_length", len(commitMessage)))
	commitMsgSpan.End()

	// Get worktree root for path normalization
	_, detectSpan := perf.Start(ctx, "detect_file_changes")
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		detectSpan.RecordError(err)
		detectSpan.End()
		return fmt.Errorf("failed to get worktree root: %w", err)
	}

	var preUntrackedFiles []string
	if preState != nil {
		logging.Debug(logCtx, "pre-prompt state",
			slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
		preUntrackedFiles = preState.PreUntrackedFiles()
	}

	// Detect file changes via git status. captureDegraded tracks whether any
	// status scan feeding this turn breached its budget, so the marker
	// persisted at turn end reflects the whole turn, not just this walk.
	captureDegraded := preState != nil && preState.UntrackedScanSkipped
	changes, err := DetectFileChanges(ctx, preUntrackedFiles)
	if err != nil {
		captureDegraded = captureDegraded || errors.Is(err, gitrepo.ErrStatusBudgetExceeded)
		logStatusDegrade(logCtx, "failed to compute file changes", err)
	}
	if changes != nil && preState != nil && preState.UntrackedScanSkipped {
		// The turn-start untracked scan was skipped (e.g. status-walk budget
		// breach), so there is no baseline: every untracked file in the
		// worktree would be misreported as created by this turn.
		logging.Warn(logCtx, "skipping new-file detection: pre-prompt untracked scan was skipped")
		changes.New = nil
	}
	detectSpan.End()

	// Filter and normalize all paths
	_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	var relNewFiles, relDeletedFiles []string
	if changes != nil {
		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)

		// Merge git-status modified files as a fallback for transcript parsing.
		// Transcript parsing is the primary source for modified files, but it can miss
		// files if the agent uses an unrecognized tool or the transcript format changes.
		// Git status catches any tracked file with working-tree changes.
		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
	}

	// Filter transcript-extracted files to exclude files already committed to HEAD.
	// When an agent commits files mid-turn, those files are condensed by PostCommit
	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
	// if it exists in HEAD with the same content as the working tree.
	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
	normalizeSpan.End()

	// Check if there are any changes
	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
	if totalChanges == 0 {
		logging.Info(logCtx, "no files modified during session, skipping checkpoint")
		recordCaptureDegraded(ctx, sessionID, captureDegraded)
		transitionSessionTurnEnd(ctx, sessionID, event, capturedTranscript, repeatableTurnEnd)
		if !repeatableTurnEnd {
			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
					slog.String("error", cleanupErr.Error()))
			}
		}
		return nil
	}

	// Log file changes
	logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)

	// Get git author
	author, err := GetGitAuthor(ctx)
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Get strategy and agent type
	strat := GetStrategy(ctx)
	agentType := ag.Type()

	// Agents that run subagents as sessions of their own (Factory AI Droid's
	// Workers) reach turn-end here for the subagent's own turn. Attribute that
	// work to the parent task invocation instead of minting a top-level session
	// checkpoint unrelated to the session the user is actually driving.
	if link, isSubagent := resolveSubagentSessionLink(ctx, ag, transcriptRef); isSubagent {
		return saveSubagentSessionTaskStep(ctx, subagentSessionStep{
			link:          link,
			sessionID:     sessionID,
			event:         event,
			transcriptRef: transcriptRef,
			modifiedFiles: relModifiedFiles,
			newFiles:      relNewFiles,
			deletedFiles:  relDeletedFiles,
			agentType:     agentType,
			strat:         strat,
		})
	}

	// Get transcript position/identifier from pre-prompt state
	var transcriptIdentifierAtStart string
	var transcriptLinesAtStart int
	if preState != nil {
		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
		transcriptLinesAtStart = preState.TranscriptOffset
	}

	// Resolve token usage. Hook-provided counts (e.g., Cursor's stop hook,
	// which is the only authoritative source for Cursor sessions because the
	// JSONL transcript has no usage fields) take precedence; otherwise fall
	// back to transcript-based computation, preferring SubagentAwareExtractor
	// to include subagent tokens.
	tokenUsage := event.TokenUsage
	if tokenUsage == nil {
		tokenUsage = analyzedTokenUsage
		if tokenUsage == nil {
			tokenUsage = agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
		}
	}

	// Persist the producer path as the session reference for future turns. This
	// Stop's finalization receives capturedTranscript separately and must not read
	// the path through StepContext or SessionState.
	stepCtx := strategy.StepContext{
		SessionID:                sessionID,
		ModifiedFiles:            relModifiedFiles,
		NewFiles:                 relNewFiles,
		DeletedFiles:             relDeletedFiles,
		MetadataDir:              sessionDir,
		MetadataDirAbs:           sessionDirAbs,
		CommitMessage:            commitMessage,
		TranscriptPath:           transcriptRef,
		AuthorName:               author.Name,
		AuthorEmail:              author.Email,
		AgentType:                agentType,
		StepTranscriptIdentifier: transcriptIdentifierAtStart,
		StepTranscriptStart:      transcriptLinesAtStart,
		TokenUsage:               tokenUsage,
	}

	// finishTurn is the shared turn-end tail, run whether the save succeeded
	// or was skipped on a status budget breach. The LastPrompt backfill must
	// come after SaveStep because SaveStep may reinitialize session state,
	// which would overwrite an earlier LastPrompt update — and SaveStep has
	// initialized state even when it then failed on the budget.
	finishTurn := func(degraded bool) {
		if backfilledPrompt != "" {
			mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
				if state.LastPrompt != "" {
					return strategy.ErrMutationSkip
				}
				state.LastPrompt = backfilledPrompt
				return nil
			})
			if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
				logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
					slog.String("error", mutErr.Error()))
			}
		}
		recordCaptureDegraded(ctx, sessionID, degraded)
		transitionSessionTurnEnd(ctx, sessionID, event, capturedTranscript, repeatableTurnEnd)
		if !repeatableTurnEnd {
			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
					slog.String("error", cleanupErr.Error()))
			}
		}
	}

	if err := strat.SaveStep(ctx, stepCtx); err != nil {
		if errors.Is(err, gitrepo.ErrStatusBudgetExceeded) {
			// The first-checkpoint status read inside the save breached its
			// budget. Hooks must never fail on status cost — skip this turn's
			// checkpoint, run the normal turn-end bookkeeping, and exit 0.
			logging.Warn(logCtx, "checkpoint skipped: status budget exceeded during save; capture degraded this turn",
				slog.String("error", err.Error()))
			finishTurn(true)
			return nil
		}
		return fmt.Errorf("failed to save step: %w", err)
	}

	finishTurn(captureDegraded)
	return nil
}

// handleLifecycleCompaction handles context compaction: saves current progress
// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
// Also resets the transcript offset since the transcript may be truncated.
func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "compaction",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
		logging.Debug(logCtx, "session state found, parsing transcript from offset",
			slog.Int("offset", sessionState.CheckpointTranscriptStart))
		return sessionState.CheckpointTranscriptStart
	}

	return 0
}

// recordCaptureDegraded persists (or clears) the capture-degraded timestamp on
// session state at turn end, so a status-budget breach is visible in
// `entire status` instead of only in .entire/logs. A healthy turn clears it —
// the marker means "the LAST turn degraded", not "some turn once did". Skips
// the state write when nothing changes, which is the common case.
func recordCaptureDegraded(ctx context.Context, sessionID string, degraded bool) {
	mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		if !degraded && state.CaptureDegradedAt == nil {
			return strategy.ErrMutationSkip
		}
		state.CaptureDegradedAt = nil
		if degraded {
			now := time.Now().UTC()
			state.CaptureDegradedAt = &now
		}
		return nil
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to record capture degradation in session state",
			slog.String("error", mutErr.Error()))
	}
}

// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
// Passing the capture explicitly prevents finalization and position advancement
// for this Stop from falling back to SessionState.TranscriptPath.
func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event, capturedTranscript *agent.TranscriptSnapshot, repeatable bool) {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, sessionID, func(state *strategy.SessionState) error {
		appendedSkillEvents = persistEventMetadataToState(event, state)
		state.TurnEndPending = repeatable
		if err := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
			logging.Warn(logCtx, "turn-end transition failed",
				slog.String("error", err.Error()))
		}
		// HandleTurnEnd mutates state in-place; the outer MutateSessionState
		// save flushes those changes. Any reentrant MutateSessionState calls
		// it makes on this session ID share this state pointer via the gate —
		// and any post-save effect they register is flushed by this frame.
		strat := GetStrategy(ctx)
		// The turn-end finalize extracts skill events from the full transcript
		// and appends the new ones to state.SkillEvents — snapshot its growth
		// so those events reach telemetry alongside the hook-provided ones.
		skillEventsBefore := len(state.SkillEvents)
		if err := strat.HandleTurnEnd(ctx, state, capturedTranscript); err != nil {
			logging.Warn(logCtx, "turn-end action dispatch failed",
				slog.String("error", err.Error()))
		}
		// Guarded rather than sliced blind: nothing shortens SkillEvents today,
		// but a future path that rewrote or trimmed the list would turn this
		// into a panic in a hook.
		if len(state.SkillEvents) > skillEventsBefore {
			appendedSkillEvents = append(appendedSkillEvents, state.SkillEvents[skillEventsBefore:]...)
		}
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to update session phase on turn end",
			slog.String("error", mutErr.Error()))
	}
}

// sessionEndedAt resolves the EndedAt stamp for a session being finalized under
// the given policy. endedWhenLastSeen falls back through the state's own record
// of activity and never yields a zero time: an unknown last-seen is stamped now,
// which is what the old unconditional behavior did anyway.
func sessionEndedAt(state *strategy.SessionState, when endedAtPolicy) time.Time {
	if when == endedWhenLastSeen {
		if state.LastInteractionTime != nil && !state.LastInteractionTime.IsZero() {
			return *state.LastInteractionTime
		}
		if !state.StartedAt.IsZero() {
			return state.StartedAt
		}
	}
	return time.Now()
}

// endedAtPolicy selects the timestamp written to SessionState.EndedAt.
type endedAtPolicy int

const (
	// endedNow stamps the current time: the session is ending as we watch it,
	// driven by its own session-end hook or by `entire session stop`.
	endedNow endedAtPolicy = iota

	// endedWhenLastSeen stamps the session's last known activity instead, for
	// finalizations that discover an end that already happened. The exited-owner
	// sweep is the case: the agent quit at some unknown earlier point, and since
	// the sweep covers IDLE and state files live for StaleSessionThreshold, the
	// first run after an upgrade can finalize sessions abandoned days ago.
	//
	// Stamping "now" on those dates a week-old session to today, which floats it
	// above genuinely recent work in the `entire session resume` picker
	// (sessionLastActiveTime prefers EndedAt) and makes `entire session info`
	// report it as just-ended. Only display and ordering read the value — nothing
	// keys retention off it — so the older, truer timestamp is strictly better.
	endedWhenLastSeen
)

// markSessionEnded transitions the session to ENDED phase via the state machine.
// If event is non-nil, hook-provided metrics are persisted to state before saving.
// markSessionEnded fires the SessionStop transition (PhaseEnded + EndedAt) under
// the session-state lock. When guard is non-nil and returns false on the
// freshly-loaded state, the transition is skipped — callers use it to
// re-validate a precondition that may have changed since their snapshot (the
// exited-session sweep re-checks OwnerExited under the lock so it never ends a
// session a concurrent turn just revived). It reports whether the session was
// actually ended.
func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string, guard func(*strategy.SessionState) bool, when endedAtPolicy) (ended bool, err error) {
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, sessionID, func(state *strategy.SessionState) error {
		if guard != nil && !guard(state) {
			return strategy.ErrMutationSkip
		}
		if event != nil {
			appendedSkillEvents = persistEventMetadataToState(event, state)
		}
		// Resolved before the transition, which is not a read-only step: the
		// SessionStop edge carries ActionUpdateLastInteraction and stamps
		// LastInteractionTime with now — exactly the value endedWhenLastSeen
		// needs, so reading it afterwards always yields "now".
		endedAt := sessionEndedAt(state, when)
		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
				slog.String("error", transErr.Error()))
		}
		state.EndedAt = &endedAt
		sealPendingTurnAtSessionEnd(state)
		if prepareErr := strategy.PrepareSessionEndCondensation(ctx, state); prepareErr != nil {
			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to prepare session-end condensation",
				slog.String("session_id", sessionID),
				slog.String("error", prepareErr.Error()))
		}
		ended = true
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if errors.Is(mutErr, strategy.ErrStateNotFound) || errors.Is(mutErr, strategy.ErrMutationSkip) {
		return false, nil
	}
	if mutErr != nil {
		return false, fmt.Errorf("failed to save session state: %w", mutErr)
	}
	return ended, nil
}

func sealPendingTurnAtSessionEnd(state *strategy.SessionState) {
	if state.TurnEndPending && !state.TurnEndRefreshFailed {
		state.TurnCheckpointIDs = nil
	}
	state.TurnEndPending = false
}

// logFileChanges logs the files modified, created, and deleted during a session.
func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	logging.Debug(logCtx, "files changed during session",
		slog.Int("modified", len(modified)),
		slog.Int("new", len(newFiles)),
		slog.Int("deleted", len(deleted)))
}

// persistEventMetadataToState returns the skill events newly appended to
// state so callers can forward them to telemetry AFTER their surrounding
// MutateSessionState closure releases the session gate — settings load and
// detached-process spawn must never run while the lock is held.
func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) []agent.SkillEvent {
	// Update ModelName if provided (model is known by turn-end even on first turn)
	if event.Model != "" {
		state.ModelName = event.Model
	}
	appendedSkillEvents := appendEventSkillEventsToState(event, state)

	// Persist hook-provided session metrics (e.g., from Cursor hooks)
	if event.DurationMs > 0 {
		state.SessionDurationMs = event.DurationMs
	}
	// Use hook-reported turn count if available (take max); otherwise
	// increment on each TurnEnd event to count turns ourselves.
	prevTurnCount := state.SessionTurnCount
	if event.TurnCount > 0 {
		if event.TurnCount > state.SessionTurnCount {
			state.SessionTurnCount = event.TurnCount
		}
	} else if event.Type == agent.TurnEnd {
		state.SessionTurnCount++
	}
	// Deferred checkpoint-window reset: the first time the turn count actually
	// advances after a checkpoint was written, re-anchor the window base to the
	// count from before this turn so the current turn becomes the first prompt of
	// the new window. Gate on a real advance (not just a TurnEnd / non-zero
	// TurnCount) so a repeated or stale hook reporting the same cumulative count
	// InvestigateRunID is the 12-hex-char ID of the parent investigation
	// run when Kind is an investigate kind. Multiple sessions across rounds
	// share this ID so the loop driver can correlate them. Empty for
	// non-investigate sessions.
	InvestigateRunID string `json:"investigate_run_id,omitempty"`

	// InvestigateTopic is the human-readable topic the investigation was
	// asked to investigate. Snapshot at session start so checkpoint
	// metadata records what the agent was investigating. Only meaningful
	// when Kind is an investigate kind.
	InvestigateTopic string `json:"investigate_topic,omitempty"`

	// TurnID is a unique identifier for the current agent turn.
	// Lifecycle:
	//   - Generated fresh in InitializeSession at each turn start
	//   - Shared across all checkpoints within the same turn
	//   - Used to correlate related checkpoints when a turn's work spans multiple commits
	//   - Persists until the next InitializeSession call generates a new one
	TurnID string `json:"turn_id,omitempty"`

	// TurnCheckpointIDs tracks all checkpoint IDs condensed during the current turn.
	// Lifecycle:
	//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
	//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
	//   - Retained across repeatable turn-end events so a continuation can refresh them
	//   - Otherwise cleared in HandleTurnEnd after finalization completes
	//   - Cleared in InitializeSession when a new prompt starts
	//   - Cleared when session is reset (ResetSession deletes the state file entirely)
	TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

	// TurnEndPending keeps the current turn's checkpoint IDs recoverable after
	// a repeatable turn-end event. A later turn-end refreshes those checkpoints;
	// the next user prompt or session end seals the turn and clears this flag.
	TurnEndPending bool `json:"turn_end_pending,omitempty"`

	// TurnEndRefreshFailed preserves checkpoint IDs at session end when the most
	// recent repeatable turn-end could not refresh them.
	TurnEndRefreshFailed bool `json:"turn_end_refresh_failed,omitempty"`

	// LastInteractionTime is updated on agent-interaction events (TurnStart,
	// TurnEnd, SessionStop, Compaction) but NOT on git commit hooks.
	// Used for stale session detection in "entire doctor".
	LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`

	// CaptureDegradedAt records when the session's most recent turn degraded
	// capture because a worktree status scan breached its budget (new-file
	file, err := tree.File(promptPath)
	if err != nil {
		return nil
	}

	content, err := file.Contents()
	if err != nil {
		return nil
	}

	return splitPromptContent(content)
}

// errPartialState signals InitializeSession's mutation callback that the
// loaded state has an empty BaseCommit (left over from a concurrent warning
// that wrote partial state). The caller falls through to initializeSession
// to repair it.
var errPartialState = errors.New("partial session state")

// HandleTurnEnd dispatches strategy-specific actions emitted when an agent turn ends.
// The primary job is to finalize all checkpoints from this turn with the full transcript.
//
// During a turn, PostCommit writes provisional transcript data (whatever was available
// at commit time). HandleTurnEnd replaces that with the complete session transcript
// (from prompt to stop event), ensuring every checkpoint has the full context.
//

func (s *ManualCommitStrategy) HandleTurnEnd(ctx context.Context, state *SessionState, capturedTranscript *agent.TranscriptSnapshot) error { //nolint:unparam // error return is part of the hook contract; callers check it
	hadMidTurnCommits := len(state.TurnCheckpointIDs) > 0

	// Finalize all checkpoints from this turn with the full transcript.
	//
	// IMPORTANT: This is best-effort - errors are logged but don't fail the hook.
	// Failing here would prevent session cleanup and could leave state inconsistent.
	// The provisional transcript from PostCommit is already persisted, so the
	// checkpoint isn't lost - it just won't have the complete transcript.
	errCount := s.finalizeAllTurnCheckpoints(ctx, state, capturedTranscript)
	if state.TurnEndPending {
		state.TurnEndRefreshFailed = errCount > 0
	}
	if errCount > 0 {
		logCtx := logging.WithComponent(ctx, "checkpoint")
		logging.Warn(logCtx, "HandleTurnEnd completed with errors (best-effort)",
			slog.String("session_id", state.SessionID),
			slog.Int("error_count", errCount),
		)
	}

	// Advance CheckpointTranscriptStart to the actual transcript end after
	// mid-turn commits. When an agent commits mid-turn (e.g., Codex "commit/push"),
	// condensation records TotalTranscriptLines at commit time, but the agent
	// continues writing to the transcript (tool results, token counts, task_complete).
	// Without this fix, the next checkpoint's scoped transcript starts mid-turn,
	// including a tail of already-condensed content.
	//
	// Skip this when carry-forward is active. carryForwardToNewShadowBranch
	// intentionally resets CheckpointTranscriptStart to 0 so the next checkpoint
	// remains self-contained with the full transcript.
	hasTranscript := capturedTranscript != nil || state.TranscriptPath != ""
	if hadMidTurnCommits && hasTranscript && len(state.FilesTouched) == 0 {
		position := 0
		if capturedTranscript != nil {
			position = capturedTranscript.Position
		} else if transcriptPath, resolveErr := resolveTranscriptPath(state); resolveErr == nil {
			if ag, agErr := agent.GetByAgentType(state.AgentType); agErr == nil {
				if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
					if measuredPosition, positionErr := analyzer.GetTranscriptPosition(transcriptPath); positionErr == nil {
						position = measuredPosition
					}
				}
			}
		}
		if position > state.CheckpointTranscriptStart {
			logging.Debug(logging.WithComponent(ctx, "hooks"),
				"advancing CheckpointTranscriptStart to turn end after mid-turn commit",
				slog.String("session_id", state.SessionID),
				slog.Int("old_offset", state.CheckpointTranscriptStart),
				slog.Int("new_offset", position),
			)
			state.CheckpointTranscriptStart = position
		}
	}

	return nil
}

func clearFinalizedTurnCheckpointIDs(state *SessionState) {
	if !state.TurnEndPending {
		state.TurnCheckpointIDs = nil
	}
}

// precomputeTranscriptBlobsForFinalize chunks + zlib-compresses the redacted
// transcript once for reuse across every checkpoint in the turn. Returns nil
// (without error) when the transcript is empty — downstream stores skip
// transcript updates in that case, so precompute would only write a wasted
// empty-chunk blob to the object store. On failure, logs a warning and
// returns nil so the loop falls back to per-checkpoint chunking.
func precomputeTranscriptBlobsForFinalize(ctx context.Context, repo *git.Repository, transcript redact.RedactedBytes, state *SessionState) *checkpoint.PrecomputedTranscriptBlobs {
	if transcript.Len() == 0 {
		return nil
	}
	_, span := perf.Start(ctx, "precompute_transcript_blobs")
	defer span.End()
	precomputed, err := checkpoint.PrecomputeTranscriptBlobs(ctx, repo, transcript, state.AgentType)
	if err != nil {
		logging.Warn(ctx, "finalize: precompute transcript blobs failed, falling back to per-checkpoint work",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return nil
	}
	return precomputed
}

func readTranscriptForFinalize(state *SessionState, capturedTranscript *agent.TranscriptSnapshot) ([]byte, error) {
	if capturedTranscript != nil {
		// The Stop capture is authoritative. Reopening the source here would
		// reintroduce the readiness/read race that capture is meant to close.
		return bytes.Clone(capturedTranscript.Data), nil
	}

	// Non-capturing agents retain path re-resolution because some relocate
	// transcripts mid-session (for example Cursor's flat-to-nested move).
	if state.TranscriptPath == "" {
		return nil, errors.New("no transcript path")
	}
	transcriptPath, err := resolveTranscriptPath(state)
	if err != nil {
		return nil, fmt.Errorf("resolve transcript path: %w", err)
	}
	data, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return data, nil
}

// redactFinalizedTranscript redacts the finalized full-session transcript,
// delegating to redactSessionTranscript so finalize and post-commit condensation
// share one pipeline. That sharing is load-bearing, not tidiness: both store the
// same sanitized, image-externalized bytes for the same session under the same
// prefix-cache key, so a divergence between them would splice a prefix produced
// by one pipeline onto a suffix produced by the other. Going through the same
// function -- including its injectable redactSessionJSONLBytes seam -- makes that
// impossible rather than merely unlikely.
//
// ok=false means abandon this finalize pass, and is returned only for a degraded
// scanner -- the caller must keep TurnCheckpointIDs so the next hook process
// retries, since the degradation flag is per-process. Any other redaction failure
// drops the transcript and returns ok=true, preserving the rest of the checkpoint
// metadata: hooks have no retry path, and partial metadata beats none.
func redactFinalizedTranscript(
	logCtx context.Context,
	repo *git.Repository,
	sessionID string,
	fullTranscript []byte,
) (transcript redact.RedactedBytes, ok bool) {
	redacted, _, err := redactSessionTranscript(logCtx, repo, sessionID, fullTranscript)
	if err == nil {
		return redacted, true
	}

	if errors.Is(err, redact.ErrScannerDegraded) {
		logging.Warn(logCtx, "finalize: transcript redaction degraded, skipping",
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, false
	}

	logging.Warn(logCtx, "finalize: transcript redaction failed, dropping transcript",
		slog.String("session_id", sessionID),
		slog.String("error", err.Error()),
	)
	return redact.RedactedBytes{}, true
}

// finalizeAllTurnCheckpoints replaces the provisional transcript in each checkpoint
// created during this turn with the full session transcript.
//
// This is called at turn end (stop hook). During the turn, PostCommit wrote whatever
// transcript was available at commit time. A repeatable turn end refreshes the
// same checkpoints on every Stop and retains their IDs until the next prompt or
// session end seals the turn.
//
// Returns the number of errors encountered (best-effort: continues processing on error).
func (s *ManualCommitStrategy) finalizeAllTurnCheckpoints(ctx context.Context, state *SessionState, capturedTranscript *agent.TranscriptSnapshot) int {
	if len(state.TurnCheckpointIDs) == 0 {
		return 0 // No mid-turn commits to finalize
	}

	logCtx := logging.WithComponent(ctx, "checkpoint")

	logging.Info(logCtx, "finalizing turn checkpoints with full transcript",
		slog.String("session_id", state.SessionID),
		slog.Int("checkpoint_count", len(state.TurnCheckpointIDs)),
	)

	errCount := 0

	fullTranscript, err := readTranscriptForFinalize(state, capturedTranscript)
	if err != nil || len(fullTranscript) == 0 {
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		clearFinalizedTurnCheckpointIDs(state)
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for shadow branch prompt reading and checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		clearFinalizedTurnCheckpointIDs(state)
		return 1 // Count as error - all checkpoints will be skipped
	}
	defer repo.Close()
	policy, err := readLocalCheckpointPolicy(logCtx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(logCtx, err)
		clearFinalizedTurnCheckpointIDs(state)
		return 1
	}
	if !checkpointpolicy.CanSatisfyPolicy(policy) {
		warnIfCheckpointPolicyNeedsUpgrade(logCtx, policy)
		clearFinalizedTurnCheckpointIDs(state)
		return 1
	}

	prompts := readPromptsFromShadowBranch(ctx, repo, state)
	if len(prompts) == 0 {
		prompts = readPromptsFromFilesystem(ctx, state.SessionID)
	}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; ExtractSkillEvents handles nil
	// Persist newly extracted events into state (the caller's MutateSessionState
	// saves them); telemetry for them is emitted by the lifecycle turn-end
	// handler, which snapshots state.SkillEvents growth around HandleTurnEnd.
	_, skillEvents := persistNewSkillEvents(state, agent.ExtractSkillEvents(ctx, ag, fullTranscript, 0))

	// Sanitize before externalizing and redacting, matching CondenseSession's
	// sanitize -> externalize -> redact order. Skill events above are extracted from
	// the pre-sanitization bytes because they are session telemetry rather than
	// stored transcript content.
	fullTranscript = agent.SanitizeTranscriptForStorage(ag, fullTranscript)

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (attribution, files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	// Run the regex-only pipeline over the transcript — OPF runs later in
	// the pre-push rewrite path, which re-redacts these regex-only blobs
	// and produces OPF-applied (9-layer) commits before the push goes out.
	// Externalize inline images BEFORE redaction, mirroring CondenseSession, so the
	// finalized (authoritative, full-session) transcript keeps its placeholders and
	// matching assets instead of re-inlining what condensation lifted out. Opt-in;
	// a no-codec agent or a transcript with no images is a no-op.
	var finalizeAssets []checkpoint.TranscriptAsset
	// Whether externalization actually RAN at finalize. When it did not (flag
	// off here even though it may have been on at condensation — e.g. an
	// ENTIRE_EXTERNALIZE_IMAGES env override not inherited by the hook
	// process, or settings toggled mid-session), an empty finalizeAssets means
	// "extraction didn't run", NOT "the transcript has no images" — clearing
	// the previously-stored assets would permanently lose them (the re-inlined
	// base64 is destroyed by redaction below).
	externalizationRan := false
	if settings.IsImageExternalizationEnabled(ctx) {
		rewritten, assets, exErr := extractSessionImages(state.AgentType, fullTranscript)
		if exErr != nil {
			logging.Warn(logCtx, "finalize: image externalization failed; leaving transcript inline",
				slog.String("session_id", state.SessionID),
				slog.String("error", exErr.Error()),
			)
		} else {
			fullTranscript = rewritten
			finalizeAssets = assets
			externalizationRan = true
		}
	}
	// Re-capture sidecar images (e.g. Cursor's SQLite store) so a finalize that
	// rewrites the transcript re-writes them too. When the full transcript differs
	// from the stored (mid-turn) one, writeAssets clears the whole assets/ folder
	// and re-writes only these assets — omitting the sidecar images here would drop
	// what CondenseSession captured. Content-hash names make this idempotent with
	// condensation's write; when the transcript is unchanged, writeAssets is not
	// called and condensation's assets are left intact.
	finalizeAssets = append(finalizeAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)
	// Sidecar capture is best-effort: a transient miss here (sqlite3 locked/timed
	// out) yields no assets. For a sidecar-capable agent, preserve the assets a
	// prior condensation stored rather than letting an empty set clear them.
	_, sidecarCapable := agent.AsSidecarImageProvider(ag)

	redactedTranscript, redactOK := redactFinalizedTranscript(logCtx, repo, state.SessionID, fullTranscript)
	if !redactOK {
		return 1
	}

	// Post-commit emits regex-only blobs; the writer joins + redacts
	// via checkpoint.redactedJoinedPrompts. OPF runs later, once per
	// push, in the pre-push rewrite path.
	// RefFetcher: the transcript finalize targets existing checkpoints whose
	// refs may live only on the remote (resumed/adopted multi-machine
	// sessions). Bounded budget + the store's failure memo keep a dead
	// network from stalling the stop hook N times.
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{
		RefFetcher:  remote.HookCheckpointRefFetcher(),
		ReadRemotes: CheckpointReadRemotes(ctx),
	})
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)

	// Update each checkpoint with the full transcript
	for _, cpIDStr := range state.TurnCheckpointIDs {
		cpID, parseErr := id.NewCheckpointID(cpIDStr)
		if parseErr != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", parseErr.Error()),
			)
			errCount++
			continue
		}

		updateOpts := checkpoint.UpdateOptions{
			CheckpointID:            cpID,
			SessionID:               state.SessionID,
			Transcript:              redactedTranscript,
			Assets:                  finalizeAssets,
			PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
			Prompts:                 prompts,
			Agent:                   state.AgentType,
			SkillEvents:             skillEvents,
			PrecomputedBlobs:        precomputed,
		}

		updateErr := store.Write(ctx, checkpoint.SessionTranscript(updateOpts))
		if updateErr != nil {
			logging.Warn(logCtx, "finalize: failed to update checkpoint",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", updateErr.Error()),
			)
			errCount++
			continue
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}

	// Clear turn checkpoint IDs unless another Stop can extend this turn. Do NOT
	// update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardToNewShadowBranch resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	clearFinalizedTurnCheckpointIDs(state)

	return errCount
}

// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
// break downstream condensation and carry-forward logic.
func filesChangedInCommit(ctx context.Context, repoDir string, commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
	var parentHash string
	if commit.NumParents() > 0 {
		parentHash = commit.ParentHashes[0].String()

item.aggregated_output:
	logging.Info(logCtx, "turn-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	sessionID := event.SessionID
	if sessionID == "" {
		sessionID = unknownSessionID
	}
	repeatableTurnEnd := false
	if repeatable, ok := agent.AsRepeatableTurnEnd(ag); ok {
		repeatableTurnEnd = repeatable.TurnEndMayRepeat()
	}

	// Fill model from hint file if the agent didn't provide it on this hook
	if event.Model == "" && sessionID != unknownSessionID {
		if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
			event.Model = hint
			logging.Debug(logCtx, "loaded model from hint file",
				slog.String("model", hint))
		}
	}

	transcriptRef := event.SessionRef
	if transcriptRef == "" {
		return errors.New("transcript file not specified")
	}

	// A capturer makes readiness and reading one ownership transfer. On success,
	// every Stop consumer below must use the returned bytes and position rather
	// than reopen transcriptRef. On failure, return before copying the transcript,
	// transitioning the session, or finalizing provisional checkpoints.
	//
	// Claude's final response is scoped to the current turn, so modern capture
	// also requires the boundary recorded at TurnStart. The explicit captured bit,
	// not a positive offset, proves that boundary was measured: zero is valid for
	// the first turn. Without it, an identical response from an earlier turn could
	// satisfy readiness.
	_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
	var preState *PrePromptState
	var capturedTranscript *agent.TranscriptSnapshot
	if capturer, ok := agent.AsTranscriptCapturer(ag); ok {
		var loadErr error
		preState, loadErr = LoadPrePromptState(ctx, sessionID)
		if loadErr != nil {
			logging.Warn(logCtx, "failed to load pre-prompt state",
				slog.String("error", loadErr.Error()))
		}
		if event.FinalResponse != nil && *event.FinalResponse != "" &&
			(preState == nil || !preState.TranscriptPositionCaptured) {
			err := fmt.Errorf("%w: final response supplied without a turn-start transcript position", agent.ErrTranscriptNotReady)
			prepareSpan.RecordError(err)
			prepareSpan.End()
			return err
		}

		startPosition := 0
		if preState != nil {
			startPosition = preState.TranscriptOffset
		}
		snapshot, captureErr := capturer.CaptureTranscript(ctx, agent.TranscriptCaptureRequest{
			SessionRef:    transcriptRef,
			StartPosition: startPosition,
			FinalResponse: event.FinalResponse,
		})
		if captureErr != nil {
			prepareSpan.RecordError(captureErr)
			prepareSpan.End()
			return fmt.Errorf("capture transcript: %w", captureErr)
		}
		capturedTranscript = &snapshot
	} else if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
		// Non-capturing agents retain prepare-then-read behavior. OpenCode needs
		// preparation to materialize its lazy transcript export.
		if prepareErr := preparer.PrepareTranscript(ctx, transcriptRef); prepareErr != nil {
			logging.Warn(logCtx, "failed to prepare transcript",
				slog.String("error", prepareErr.Error()))
		}
	}

	if capturedTranscript == nil && !fileExists(transcriptRef) {
		prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
		prepareSpan.End()
		return fmt.Errorf("transcript file not found: %s", transcriptRef)
	}

	// Early check: bail out quickly if the repo has no commits yet.
	// Return nil (not an error) so the hook exits 0 — agents treat non-zero
	// exit codes as hook failures. The user was already warned at session start.
	if repo, err := strategy.OpenRepository(ctx); err == nil {
		defer repo.Close()
		if strategy.IsEmptyRepository(repo) {
			prepareSpan.End()
			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
			return nil
		}
	}
	prepareSpan.End()

	// Create session metadata directory
	_, copySpan := perf.Start(ctx, "copy_transcript")
	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
	if err != nil {
		sessionDirAbs = sessionDir
	}
	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
		copySpan.RecordError(err)
		copySpan.End()
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Copy transcript to session directory
	var transcriptData []byte
	if capturedTranscript != nil {
		transcriptData = capturedTranscript.Data
	} else {
		transcriptData, err = ag.ReadTranscript(transcriptRef)
		if err != nil {
			copySpan.RecordError(err)
			copySpan.End()
			return fmt.Errorf("failed to read transcript: %w", err)
		}
	}
	// Sanitize before writing: this copy is what the shadow-branch walk blobs and
	// redacts on every Stop. See agent.TranscriptSanitizer for why order matters.
	// The agent's own rollout is untouched.
	storageInput := transcriptData
	if capturedTranscript != nil {
		// Snapshot bytes stay immutable while storage sanitizers run.
		storageInput = bytes.Clone(transcriptData)
	}
	storedTranscript := agent.SanitizeTranscriptForStorage(ag, storageInput)
	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
		copySpan.RecordError(err)
		copySpan.End()
		return fmt.Errorf("failed to write transcript: %w", err)
	}
	logging.Debug(logCtx, "copied transcript",
		slog.String("path", sessionDir+"/"+paths.TranscriptFileName),
		slog.Int("raw_bytes", len(transcriptData)),
		slog.Int("stored_bytes", len(storedTranscript)))
	copySpan.End()

	_, extractSpan := perf.Start(ctx, "extract_metadata")
	if capturedTranscript == nil {
		// Preserve the original non-capturing order: prepare and copy first,
		// then load the turn-start state used by metadata extraction.
		var loadErr error
		preState, loadErr = LoadPrePromptState(ctx, sessionID)
		if loadErr != nil {
			logging.Warn(logCtx, "failed to load pre-prompt state",
				slog.String("error", loadErr.Error()))
		}
	}
	// Determine transcript offset
	transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)

	// Backfill prompt.txt from transcript when prompt data is missing.
	// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
	// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
	// there genuinely were no prompts. We track whether backfill occurred so we can
	// update session state after SaveStep (which may reinitialize state).
	var backfilledPrompt string
	promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
	existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
	if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
		logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
			slog.String("error", readPromptErr.Error()))
	} else if len(existingPrompt) == 0 {
		if extractor, ok := agent.AsPromptExtractor(ag); ok {
			// A captured Stop cannot use a path-only extractor: reopening the
			// producer-owned file would discard the capture guarantee. Claude
			// records prompt.txt at TurnStart, so it does not need this fallback.
			if capturedTranscript == nil {
				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
				if extractErr != nil {
					logging.Warn(logCtx, "failed to extract prompts from transcript",
						slog.String("error", extractErr.Error()))
				} else if len(prompts) > 0 {
					content := strings.Join(prompts, "\n\n---\n\n")
					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
							slog.String("error", writeErr.Error()))
					} else {
						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
							slog.Int("prompt_count", len(prompts)))
						backfilledPrompt = prompts[len(prompts)-1]
					}
				}
			}
		}
	}

	// The source path remains authoritative for locating separate subagent files;
	// those bytes are outside the captured main transcript.
	subagentsDir := paths.SubagentsDir(filepath.Dir(transcriptRef), event.SessionID)

	// Extract metadata via agent interface (modified files)
	var modifiedFiles []string
	var analyzedTokenUsage *agent.TokenUsage

	if turnAnalyzer, ok := agent.AsTranscriptTurnAnalyzer(ag); ok && capturedTranscript != nil {
		analysis, analysisErr := turnAnalyzer.AnalyzeTranscriptTurn(transcriptData, transcriptOffset, subagentsDir)
		if analysisErr != nil {
			logging.Warn(logCtx, "failed to analyze captured transcript",
				slog.String("error", analysisErr.Error()))
		} else {
			modifiedFiles = analysis.ModifiedFiles
			analyzedTokenUsage = analysis.TokenUsage
		}
	} else if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
		// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
		if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
			if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
				logging.Warn(logCtx, "failed to extract modified files (with subagents)",
					slog.String("error", fileErr.Error()))
			} else {
				modifiedFiles = files
			}
		} else if capturedTranscript == nil {
			// Path-only analysis remains available to non-capturing agents. A
			// captured Stop may use only the byte-based analyzer above.
			// Fall back to basic extraction (main transcript only)
			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
				logging.Warn(logCtx, "failed to extract modified files",
					slog.String("error", fileErr.Error()))
			} else {
				modifiedFiles = files
			}
		}
	}
	extractSpan.End()

	// Generate commit message from last prompt (read from session state, set at TurnStart).
	// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
	// Fall back to backfilledPrompt extracted from the transcript.
	// Single load serves both prompt retrieval and backfill.
	_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
	lastPrompt := ""
	if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
		lastPrompt = sessionState.LastPrompt
	}
	// Backfill LastPrompt so `entire status` shows the prompt even when no
	// files were modified (before the early return below).
	if lastPrompt == "" && backfilledPrompt != "" {
		lastPrompt = backfilledPrompt
		mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
			if state.LastPrompt != "" {
				return strategy.ErrMutationSkip
			}
			state.LastPrompt = backfilledPrompt
			return nil
		})
		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
			logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
				slog.String("error", mutErr.Error()))
		}
	}
	commitMessage := generateCommitMessage(lastPrompt, ag.Type())
	logging.Debug(logCtx, "using commit message",
		slog.Int("message_length", len(commitMessage)))
	commitMsgSpan.End()

	// Get worktree root for path normalization
	_, detectSpan := perf.Start(ctx, "detect_file_changes")
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		detectSpan.RecordError(err)
		detectSpan.End()
		return fmt.Errorf("failed to get worktree root: %w", err)
	}

	var preUntrackedFiles []string
	if preState != nil {
		logging.Debug(logCtx, "pre-prompt state",
			slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
		preUntrackedFiles = preState.PreUntrackedFiles()
	}

	// Detect file changes via git status. captureDegraded tracks whether any
	// status scan feeding this turn breached its budget, so the marker
	// persisted at turn end reflects the whole turn, not just this walk.
	captureDegraded := preState != nil && preState.UntrackedScanSkipped
	changes, err := DetectFileChanges(ctx, preUntrackedFiles)
	if err != nil {
		captureDegraded = captureDegraded || errors.Is(err, gitrepo.ErrStatusBudgetExceeded)
		logStatusDegrade(logCtx, "failed to compute file changes", err)
	}
	if changes != nil && preState != nil && preState.UntrackedScanSkipped {
		// The turn-start untracked scan was skipped (e.g. status-walk budget
		// breach), so there is no baseline: every untracked file in the
		// worktree would be misreported as created by this turn.
		logging.Warn(logCtx, "skipping new-file detection: pre-prompt untracked scan was skipped")
		changes.New = nil
	}
	detectSpan.End()

	// Filter and normalize all paths
	_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
	var relNewFiles, relDeletedFiles []string
	if changes != nil {
		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)

		// Merge git-status modified files as a fallback for transcript parsing.
		// Transcript parsing is the primary source for modified files, but it can miss
		// files if the agent uses an unrecognized tool or the transcript format changes.
		// Git status catches any tracked file with working-tree changes.
		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
	}

	// Filter transcript-extracted files to exclude files already committed to HEAD.
	// When an agent commits files mid-turn, those files are condensed by PostCommit
	// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
	// if it exists in HEAD with the same content as the working tree.
	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
	normalizeSpan.End()

	// Check if there are any changes
	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
	if totalChanges == 0 {
		logging.Info(logCtx, "no files modified during session, skipping checkpoint")
		recordCaptureDegraded(ctx, sessionID, captureDegraded)
		transitionSessionTurnEnd(ctx, sessionID, event, capturedTranscript, repeatableTurnEnd)
		if !repeatableTurnEnd {
			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
					slog.String("error", cleanupErr.Error()))
			}
		}
		return nil
	}

	// Log file changes
	logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)

	// Get git author
	author, err := GetGitAuthor(ctx)
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	// Get strategy and agent type
	strat := GetStrategy(ctx)
	agentType := ag.Type()

	// Agents that run subagents as sessions of their own (Factory AI Droid's
	// Workers) reach turn-end here for the subagent's own turn. Attribute that
	// work to the parent task invocation instead of minting a top-level session
	// checkpoint unrelated to the session the user is actually driving.
	if link, isSubagent := resolveSubagentSessionLink(ctx, ag, transcriptRef); isSubagent {
		return saveSubagentSessionTaskStep(ctx, subagentSessionStep{
			link:          link,
			sessionID:     sessionID,
			event:         event,
			transcriptRef: transcriptRef,
			modifiedFiles: relModifiedFiles,
			newFiles:      relNewFiles,
			deletedFiles:  relDeletedFiles,
			agentType:     agentType,
			strat:         strat,
		})
	}

	// Get transcript position/identifier from pre-prompt state
	var transcriptIdentifierAtStart string
	var transcriptLinesAtStart int
	if preState != nil {
		transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
		transcriptLinesAtStart = preState.TranscriptOffset
	}

	// Resolve token usage. Hook-provided counts (e.g., Cursor's stop hook,
	// which is the only authoritative source for Cursor sessions because the
	// JSONL transcript has no usage fields) take precedence; otherwise fall
	// back to transcript-based computation, preferring SubagentAwareExtractor
	// to include subagent tokens.
	tokenUsage := event.TokenUsage
	if tokenUsage == nil {
		tokenUsage = analyzedTokenUsage
		if tokenUsage == nil {
			tokenUsage = agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
		}
	}

	// Persist the producer path as the session reference for future turns. This
	// Stop's finalization receives capturedTranscript separately and must not read
	// the path through StepContext or SessionState.
	stepCtx := strategy.StepContext{
		SessionID:                sessionID,
		ModifiedFiles:            relModifiedFiles,
		NewFiles:                 relNewFiles,
		DeletedFiles:             relDeletedFiles,
		MetadataDir:              sessionDir,
		MetadataDirAbs:           sessionDirAbs,
		CommitMessage:            commitMessage,
		TranscriptPath:           transcriptRef,
		AuthorName:               author.Name,
		AuthorEmail:              author.Email,
		AgentType:                agentType,
		StepTranscriptIdentifier: transcriptIdentifierAtStart,
		StepTranscriptStart:      transcriptLinesAtStart,
		TokenUsage:               tokenUsage,
	}

	// finishTurn is the shared turn-end tail, run whether the save succeeded
	// or was skipped on a status budget breach. The LastPrompt backfill must
	// come after SaveStep because SaveStep may reinitialize session state,
	// which would overwrite an earlier LastPrompt update — and SaveStep has
	// initialized state even when it then failed on the budget.
	finishTurn := func(degraded bool) {
		if backfilledPrompt != "" {
			mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
				if state.LastPrompt != "" {
					return strategy.ErrMutationSkip
				}
				state.LastPrompt = backfilledPrompt
				return nil
			})
			if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
				logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
					slog.String("error", mutErr.Error()))
			}
		}
		recordCaptureDegraded(ctx, sessionID, degraded)
		transitionSessionTurnEnd(ctx, sessionID, event, capturedTranscript, repeatableTurnEnd)
		if !repeatableTurnEnd {
			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
					slog.String("error", cleanupErr.Error()))
			}
		}
	}

	if err := strat.SaveStep(ctx, stepCtx); err != nil {
		if errors.Is(err, gitrepo.ErrStatusBudgetExceeded) {
			// The first-checkpoint status read inside the save breached its
			// budget. Hooks must never fail on status cost — skip this turn's
			// checkpoint, run the normal turn-end bookkeeping, and exit 0.
			logging.Warn(logCtx, "checkpoint skipped: status budget exceeded during save; capture degraded this turn",
				slog.String("error", err.Error()))
			finishTurn(true)
			return nil
		}
		return fmt.Errorf("failed to save step: %w", err)
	}

	finishTurn(captureDegraded)
	return nil
}

// handleLifecycleCompaction handles context compaction: saves current progress
// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
// Also resets the transcript offset since the transcript may be truncated.
func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "compaction",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if sessionState != nil && sessionState.CheckpointTranscriptStart > 0 {
		logging.Debug(logCtx, "session state found, parsing transcript from offset",
			slog.Int("offset", sessionState.CheckpointTranscriptStart))
		return sessionState.CheckpointTranscriptStart
	}

	return 0
}

// recordCaptureDegraded persists (or clears) the capture-degraded timestamp on
// session state at turn end, so a status-budget breach is visible in
// `entire status` instead of only in .entire/logs. A healthy turn clears it —
// the marker means "the LAST turn degraded", not "some turn once did". Skips
// the state write when nothing changes, which is the common case.
func recordCaptureDegraded(ctx context.Context, sessionID string, degraded bool) {
	mutErr := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		if !degraded && state.CaptureDegradedAt == nil {
			return strategy.ErrMutationSkip
		}
		state.CaptureDegradedAt = nil
		if degraded {
			now := time.Now().UTC()
			state.CaptureDegradedAt = &now
		}
		return nil
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to record capture degradation in session state",
			slog.String("error", mutErr.Error()))
	}
}

// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
// Passing the capture explicitly prevents finalization and position advancement
// for this Stop from falling back to SessionState.TranscriptPath.
func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event, capturedTranscript *agent.TranscriptSnapshot, repeatable bool) {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, sessionID, func(state *strategy.SessionState) error {
		appendedSkillEvents = persistEventMetadataToState(event, state)
		state.TurnEndPending = repeatable
		if err := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
			logging.Warn(logCtx, "turn-end transition failed",
				slog.String("error", err.Error()))
		}
		// HandleTurnEnd mutates state in-place; the outer MutateSessionState
		// save flushes those changes. Any reentrant MutateSessionState calls
		// it makes on this session ID share this state pointer via the gate —
		// and any post-save effect they register is flushed by this frame.
		strat := GetStrategy(ctx)
		// The turn-end finalize extracts skill events from the full transcript
		// and appends the new ones to state.SkillEvents — snapshot its growth
		// so those events reach telemetry alongside the hook-provided ones.
		skillEventsBefore := len(state.SkillEvents)
		if err := strat.HandleTurnEnd(ctx, state, capturedTranscript); err != nil {
			logging.Warn(logCtx, "turn-end action dispatch failed",
				slog.String("error", err.Error()))
		}
		// Guarded rather than sliced blind: nothing shortens SkillEvents today,
		// but a future path that rewrote or trimmed the list would turn this
		// into a panic in a hook.
		if len(state.SkillEvents) > skillEventsBefore {
			appendedSkillEvents = append(appendedSkillEvents, state.SkillEvents[skillEventsBefore:]...)
		}
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to update session phase on turn end",
			slog.String("error", mutErr.Error()))
	}
}

// sessionEndedAt resolves the EndedAt stamp for a session being finalized under
// the given policy. endedWhenLastSeen falls back through the state's own record
// of activity and never yields a zero time: an unknown last-seen is stamped now,
// which is what the old unconditional behavior did anyway.
func sessionEndedAt(state *strategy.SessionState, when endedAtPolicy) time.Time {
	if when == endedWhenLastSeen {
		if state.LastInteractionTime != nil && !state.LastInteractionTime.IsZero() {
			return *state.LastInteractionTime
		}
		if !state.StartedAt.IsZero() {
			return state.StartedAt
		}
	}
	return time.Now()
}

// endedAtPolicy selects the timestamp written to SessionState.EndedAt.
type endedAtPolicy int

const (
	// endedNow stamps the current time: the session is ending as we watch it,
	// driven by its own session-end hook or by `entire session stop`.
	endedNow endedAtPolicy = iota

	// endedWhenLastSeen stamps the session's last known activity instead, for
	// finalizations that discover an end that already happened. The exited-owner
	// sweep is the case: the agent quit at some unknown earlier point, and since
	// the sweep covers IDLE and state files live for StaleSessionThreshold, the
	// first run after an upgrade can finalize sessions abandoned days ago.
	//
	// Stamping "now" on those dates a week-old session to today, which floats it
	// above genuinely recent work in the `entire session resume` picker
	// (sessionLastActiveTime prefers EndedAt) and makes `entire session info`
	// report it as just-ended. Only display and ordering read the value — nothing
	// keys retention off it — so the older, truer timestamp is strictly better.
	endedWhenLastSeen
)

// markSessionEnded transitions the session to ENDED phase via the state machine.
// If event is non-nil, hook-provided metrics are persisted to state before saving.
// markSessionEnded fires the SessionStop transition (PhaseEnded + EndedAt) under
// the session-state lock. When guard is non-nil and returns false on the
// freshly-loaded state, the transition is skipped — callers use it to
// re-validate a precondition that may have changed since their snapshot (the
// exited-session sweep re-checks OwnerExited under the lock so it never ends a
// session a concurrent turn just revived). It reports whether the session was
// actually ended.
func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string, guard func(*strategy.SessionState) bool, when endedAtPolicy) (ended bool, err error) {
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, sessionID, func(state *strategy.SessionState) error {
		if guard != nil && !guard(state) {
			return strategy.ErrMutationSkip
		}
		if event != nil {
			appendedSkillEvents = persistEventMetadataToState(event, state)
		}
		// Resolved before the transition, which is not a read-only step: the
		// SessionStop edge carries ActionUpdateLastInteraction and stamps
		// LastInteractionTime with now — exactly the value endedWhenLastSeen
		// needs, so reading it afterwards always yields "now".
		endedAt := sessionEndedAt(state, when)
		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
				slog.String("error", transErr.Error()))
		}
		state.EndedAt = &endedAt
		sealPendingTurnAtSessionEnd(state)
		if prepareErr := strategy.PrepareSessionEndCondensation(ctx, state); prepareErr != nil {
			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to prepare session-end condensation",
				slog.String("session_id", sessionID),
				slog.String("error", prepareErr.Error()))
		}
		ended = true
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if errors.Is(mutErr, strategy.ErrStateNotFound) || errors.Is(mutErr, strategy.ErrMutationSkip) {
		return false, nil
	}
	if mutErr != nil {
		return false, fmt.Errorf("failed to save session state: %w", mutErr)
	}
	return ended, nil
}

func sealPendingTurnAtSessionEnd(state *strategy.SessionState) {
	if state.TurnEndPending && !state.TurnEndRefreshFailed {
		state.TurnCheckpointIDs = nil
	}
	state.TurnEndPending = false
}

// logFileChanges logs the files modified, created, and deleted during a session.
func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
	logCtx := logging.WithComponent(ctx, "lifecycle")
	logging.Debug(logCtx, "files changed during session",
		slog.Int("modified", len(modified)),
		slog.Int("new", len(newFiles)),
		slog.Int("deleted", len(deleted)))
}

// persistEventMetadataToState returns the skill events newly appended to
// state so callers can forward them to telemetry AFTER their surrounding
// MutateSessionState closure releases the session gate — settings load and
// detached-process spawn must never run while the lock is held.
func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) []agent.SkillEvent {
	// Update ModelName if provided (model is known by turn-end even on first turn)
	if event.Model != "" {
		state.ModelName = event.Model
	}
	appendedSkillEvents := appendEventSkillEventsToState(event, state)

	// Persist hook-provided session metrics (e.g., from Cursor hooks)
	if event.DurationMs > 0 {
		state.SessionDurationMs = event.DurationMs
	}
	// Use hook-reported turn count if available (take max); otherwise
	// increment on each TurnEnd event to count turns ourselves.
	prevTurnCount := state.SessionTurnCount
	if event.TurnCount > 0 {
		if event.TurnCount > state.SessionTurnCount {
			state.SessionTurnCount = event.TurnCount
		}
	} else if event.Type == agent.TurnEnd {
		state.SessionTurnCount++
	}
	// Deferred checkpoint-window reset: the first time the turn count actually
	// advances after a checkpoint was written, re-anchor the window base to the
	// count from before this turn so the current turn becomes the first prompt of
	// the new window. Gate on a real advance (not just a TurnEnd / non-zero
	// TurnCount) so a repeated or stale hook reporting the same cumulative count
	// InvestigateRunID is the 12-hex-char ID of the parent investigation
	// run when Kind is an investigate kind. Multiple sessions across rounds
	// share this ID so the loop driver can correlate them. Empty for
	// non-investigate sessions.
	InvestigateRunID string `json:"investigate_run_id,omitempty"`

	// InvestigateTopic is the human-readable topic the investigation was
	// asked to investigate. Snapshot at session start so checkpoint
	// metadata records what the agent was investigating. Only meaningful
	// when Kind is an investigate kind.
	InvestigateTopic string `json:"investigate_topic,omitempty"`

	// TurnID is a unique identifier for the current agent turn.
	// Lifecycle:
	//   - Generated fresh in InitializeSession at each turn start
	//   - Shared across all checkpoints within the same turn
	//   - Used to correlate related checkpoints when a turn's work spans multiple commits
	//   - Persists until the next InitializeSession call generates a new one
	TurnID string `json:"turn_id,omitempty"`

	// TurnCheckpointIDs tracks all checkpoint IDs condensed during the current turn.
	// Lifecycle:
	//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
	//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
	//   - Retained across repeatable turn-end events so a continuation can refresh them
	//   - Otherwise cleared in HandleTurnEnd after finalization completes
	//   - Cleared in InitializeSession when a new prompt starts
	//   - Cleared when session is reset (ResetSession deletes the state file entirely)
	TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

	// TurnEndPending keeps the current turn's checkpoint IDs recoverable after
	// a repeatable turn-end event. A later turn-end refreshes those checkpoints;
	// the next user prompt or session end seals the turn and clears this flag.
	TurnEndPending bool `json:"turn_end_pending,omitempty"`

	// TurnEndRefreshFailed preserves checkpoint IDs at session end when the most
	// recent repeatable turn-end could not refresh them.
	TurnEndRefreshFailed bool `json:"turn_end_refresh_failed,omitempty"`

	// LastInteractionTime is updated on agent-interaction events (TurnStart,
	// TurnEnd, SessionStop, Compaction) but NOT on git commit hooks.
	// Used for stale session detection in "entire doctor".
	LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`

	// CaptureDegradedAt records when the session's most recent turn degraded
	// capture because a worktree status scan breached its budget (new-file
	file, err := tree.File(promptPath)
	if err != nil {
		return nil
	}

	content, err := file.Contents()
	if err != nil {
		return nil
	}

	return splitPromptContent(content)
}

// errPartialState signals InitializeSession's mutation callback that the
// loaded state has an empty BaseCommit (left over from a concurrent warning
// that wrote partial state). The caller falls through to initializeSession
// to repair it.
var errPartialState = errors.New("partial session state")

// HandleTurnEnd dispatches strategy-specific actions emitted when an agent turn ends.
// The primary job is to finalize all checkpoints from this turn with the full transcript.
//
// During a turn, PostCommit writes provisional transcript data (whatever was available
// at commit time). HandleTurnEnd replaces that with the complete session transcript
// (from prompt to stop event), ensuring every checkpoint has the full context.
//

func (s *ManualCommitStrategy) HandleTurnEnd(ctx context.Context, state *SessionState, capturedTranscript *agent.TranscriptSnapshot) error { //nolint:unparam // error return is part of the hook contract; callers check it
	hadMidTurnCommits := len(state.TurnCheckpointIDs) > 0

	// Finalize all checkpoints from this turn with the full transcript.
	//
	// IMPORTANT: This is best-effort - errors are logged but don't fail the hook.
	// Failing here would prevent session cleanup and could leave state inconsistent.
	// The provisional transcript from PostCommit is already persisted, so the
	// checkpoint isn't lost - it just won't have the complete transcript.
	errCount := s.finalizeAllTurnCheckpoints(ctx, state, capturedTranscript)
	if state.TurnEndPending {
		state.TurnEndRefreshFailed = errCount > 0
	}
	if errCount > 0 {
		logCtx := logging.WithComponent(ctx, "checkpoint")
		logging.Warn(logCtx, "HandleTurnEnd completed with errors (best-effort)",
			slog.String("session_id", state.SessionID),
			slog.Int("error_count", errCount),
		)
	}

	// Advance CheckpointTranscriptStart to the actual transcript end after
	// mid-turn commits. When an agent commits mid-turn (e.g., Codex "commit/push"),
	// condensation records TotalTranscriptLines at commit time, but the agent
	// continues writing to the transcript (tool results, token counts, task_complete).
	// Without this fix, the next checkpoint's scoped transcript starts mid-turn,
	// including a tail of already-condensed content.
	//
	// Skip this when carry-forward is active. carryForwardToNewShadowBranch
	// intentionally resets CheckpointTranscriptStart to 0 so the next checkpoint
	// remains self-contained with the full transcript.
	hasTranscript := capturedTranscript != nil || state.TranscriptPath != ""
	if hadMidTurnCommits && hasTranscript && len(state.FilesTouched) == 0 {
		position := 0
		if capturedTranscript != nil {
			position = capturedTranscript.Position
		} else if transcriptPath, resolveErr := resolveTranscriptPath(state); resolveErr == nil {
			if ag, agErr := agent.GetByAgentType(state.AgentType); agErr == nil {
				if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
					if measuredPosition, positionErr := analyzer.GetTranscriptPosition(transcriptPath); positionErr == nil {
						position = measuredPosition
					}
				}
			}
		}
		if position > state.CheckpointTranscriptStart {
			logging.Debug(logging.WithComponent(ctx, "hooks"),
				"advancing CheckpointTranscriptStart to turn end after mid-turn commit",
				slog.String("session_id", state.SessionID),
				slog.Int("old_offset", state.CheckpointTranscriptStart),
				slog.Int("new_offset", position),
			)
			state.CheckpointTranscriptStart = position
		}
	}

	return nil
}

func clearFinalizedTurnCheckpointIDs(state *SessionState) {
	if !state.TurnEndPending {
		state.TurnCheckpointIDs = nil
	}
}

// precomputeTranscriptBlobsForFinalize chunks + zlib-compresses the redacted
// transcript once for reuse across every checkpoint in the turn. Returns nil
// (without error) when the transcript is empty — downstream stores skip
// transcript updates in that case, so precompute would only write a wasted
// empty-chunk blob to the object store. On failure, logs a warning and
// returns nil so the loop falls back to per-checkpoint chunking.
func precomputeTranscriptBlobsForFinalize(ctx context.Context, repo *git.Repository, transcript redact.RedactedBytes, state *SessionState) *checkpoint.PrecomputedTranscriptBlobs {
	if transcript.Len() == 0 {
		return nil
	}
	_, span := perf.Start(ctx, "precompute_transcript_blobs")
	defer span.End()
	precomputed, err := checkpoint.PrecomputeTranscriptBlobs(ctx, repo, transcript, state.AgentType)
	if err != nil {
		logging.Warn(ctx, "finalize: precompute transcript blobs failed, falling back to per-checkpoint work",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return nil
	}
	return precomputed
}

func readTranscriptForFinalize(state *SessionState, capturedTranscript *agent.TranscriptSnapshot) ([]byte, error) {
	if capturedTranscript != nil {
		// The Stop capture is authoritative. Reopening the source here would
		// reintroduce the readiness/read race that capture is meant to close.
		return bytes.Clone(capturedTranscript.Data), nil
	}

	// Non-capturing agents retain path re-resolution because some relocate
	// transcripts mid-session (for example Cursor's flat-to-nested move).
	if state.TranscriptPath == "" {
		return nil, errors.New("no transcript path")
	}
	transcriptPath, err := resolveTranscriptPath(state)
	if err != nil {
		return nil, fmt.Errorf("resolve transcript path: %w", err)
	}
	data, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil {
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	return data, nil
}

// redactFinalizedTranscript redacts the finalized full-session transcript,
// delegating to redactSessionTranscript so finalize and post-commit condensation
// share one pipeline. That sharing is load-bearing, not tidiness: both store the
// same sanitized, image-externalized bytes for the same session under the same
// prefix-cache key, so a divergence between them would splice a prefix produced
// by one pipeline onto a suffix produced by the other. Going through the same
// function -- including its injectable redactSessionJSONLBytes seam -- makes that
// impossible rather than merely unlikely.
//
// ok=false means abandon this finalize pass, and is returned only for a degraded
// scanner -- the caller must keep TurnCheckpointIDs so the next hook process
// retries, since the degradation flag is per-process. Any other redaction failure
// drops the transcript and returns ok=true, preserving the rest of the checkpoint
// metadata: hooks have no retry path, and partial metadata beats none.
func redactFinalizedTranscript(
	logCtx context.Context,
	repo *git.Repository,
	sessionID string,
	fullTranscript []byte,
) (transcript redact.RedactedBytes, ok bool) {
	redacted, _, err := redactSessionTranscript(logCtx, repo, sessionID, fullTranscript)
	if err == nil {
		return redacted, true
	}

	if errors.Is(err, redact.ErrScannerDegraded) {
		logging.Warn(logCtx, "finalize: transcript redaction degraded, skipping",
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, false
	}

	logging.Warn(logCtx, "finalize: transcript redaction failed, dropping transcript",
		slog.String("session_id", sessionID),
		slog.String("error", err.Error()),
	)
	return redact.RedactedBytes{}, true
}

// finalizeAllTurnCheckpoints replaces the provisional transcript in each checkpoint
// created during this turn with the full session transcript.
//
// This is called at turn end (stop hook). During the turn, PostCommit wrote whatever
// transcript was available at commit time. A repeatable turn end refreshes the
// same checkpoints on every Stop and retains their IDs until the next prompt or
// session end seals the turn.
//
// Returns the number of errors encountered (best-effort: continues processing on error).
func (s *ManualCommitStrategy) finalizeAllTurnCheckpoints(ctx context.Context, state *SessionState, capturedTranscript *agent.TranscriptSnapshot) int {
	if len(state.TurnCheckpointIDs) == 0 {
		return 0 // No mid-turn commits to finalize
	}

	logCtx := logging.WithComponent(ctx, "checkpoint")

	logging.Info(logCtx, "finalizing turn checkpoints with full transcript",
		slog.String("session_id", state.SessionID),
		slog.Int("checkpoint_count", len(state.TurnCheckpointIDs)),
	)

	errCount := 0

	fullTranscript, err := readTranscriptForFinalize(state, capturedTranscript)
	if err != nil || len(fullTranscript) == 0 {
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		clearFinalizedTurnCheckpointIDs(state)
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for shadow branch prompt reading and checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		clearFinalizedTurnCheckpointIDs(state)
		return 1 // Count as error - all checkpoints will be skipped
	}
	defer repo.Close()
	policy, err := readLocalCheckpointPolicy(logCtx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(logCtx, err)
		clearFinalizedTurnCheckpointIDs(state)
		return 1
	}
	if !checkpointpolicy.CanSatisfyPolicy(policy) {
		warnIfCheckpointPolicyNeedsUpgrade(logCtx, policy)
		clearFinalizedTurnCheckpointIDs(state)
		return 1
	}

	prompts := readPromptsFromShadowBranch(ctx, repo, state)
	if len(prompts) == 0 {
		prompts = readPromptsFromFilesystem(ctx, state.SessionID)
	}

	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; ExtractSkillEvents handles nil
	// Persist newly extracted events into state (the caller's MutateSessionState
	// saves them); telemetry for them is emitted by the lifecycle turn-end
	// handler, which snapshots state.SkillEvents growth around HandleTurnEnd.
	_, skillEvents := persistNewSkillEvents(state, agent.ExtractSkillEvents(ctx, ag, fullTranscript, 0))

	// Sanitize before externalizing and redacting, matching CondenseSession's
	// sanitize -> externalize -> redact order. Skill events above are extracted from
	// the pre-sanitization bytes because they are session telemetry rather than
	// stored transcript content.
	fullTranscript = agent.SanitizeTranscriptForStorage(ag, fullTranscript)

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (attribution, files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	// Run the regex-only pipeline over the transcript — OPF runs later in
	// the pre-push rewrite path, which re-redacts these regex-only blobs
	// and produces OPF-applied (9-layer) commits before the push goes out.
	// Externalize inline images BEFORE redaction, mirroring CondenseSession, so the
	// finalized (authoritative, full-session) transcript keeps its placeholders and
	// matching assets instead of re-inlining what condensation lifted out. Opt-in;
	// a no-codec agent or a transcript with no images is a no-op.
	var finalizeAssets []checkpoint.TranscriptAsset
	// Whether externalization actually RAN at finalize. When it did not (flag
	// off here even though it may have been on at condensation — e.g. an
	// ENTIRE_EXTERNALIZE_IMAGES env override not inherited by the hook
	// process, or settings toggled mid-session), an empty finalizeAssets means
	// "extraction didn't run", NOT "the transcript has no images" — clearing
	// the previously-stored assets would permanently lose them (the re-inlined
	// base64 is destroyed by redaction below).
	externalizationRan := false
	if settings.IsImageExternalizationEnabled(ctx) {
		rewritten, assets, exErr := extractSessionImages(state.AgentType, fullTranscript)
		if exErr != nil {
			logging.Warn(logCtx, "finalize: image externalization failed; leaving transcript inline",
				slog.String("session_id", state.SessionID),
				slog.String("error", exErr.Error()),
			)
		} else {
			fullTranscript = rewritten
			finalizeAssets = assets
			externalizationRan = true
		}
	}
	// Re-capture sidecar images (e.g. Cursor's SQLite store) so a finalize that
	// rewrites the transcript re-writes them too. When the full transcript differs
	// from the stored (mid-turn) one, writeAssets clears the whole assets/ folder
	// and re-writes only these assets — omitting the sidecar images here would drop
	// what CondenseSession captured. Content-hash names make this idempotent with
	// condensation's write; when the transcript is unchanged, writeAssets is not
	// called and condensation's assets are left intact.
	finalizeAssets = append(finalizeAssets, sidecarSessionImages(ctx, logCtx, ag, state)...)
	// Sidecar capture is best-effort: a transient miss here (sqlite3 locked/timed
	// out) yields no assets. For a sidecar-capable agent, preserve the assets a
	// prior condensation stored rather than letting an empty set clear them.
	_, sidecarCapable := agent.AsSidecarImageProvider(ag)

	redactedTranscript, redactOK := redactFinalizedTranscript(logCtx, repo, state.SessionID, fullTranscript)
	if !redactOK {
		return 1
	}

	// Post-commit emits regex-only blobs; the writer joins + redacts
	// via checkpoint.redactedJoinedPrompts. OPF runs later, once per
	// push, in the pre-push rewrite path.
	// RefFetcher: the transcript finalize targets existing checkpoints whose
	// refs may live only on the remote (resumed/adopted multi-machine
	// sessions). Bounded budget + the store's failure memo keep a dead
	// network from stalling the stop hook N times.
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{
		RefFetcher:  remote.HookCheckpointRefFetcher(),
		ReadRemotes: CheckpointReadRemotes(ctx),
	})
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)

	// Update each checkpoint with the full transcript
	for _, cpIDStr := range state.TurnCheckpointIDs {
		cpID, parseErr := id.NewCheckpointID(cpIDStr)
		if parseErr != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", parseErr.Error()),
			)
			errCount++
			continue
		}

		updateOpts := checkpoint.UpdateOptions{
			CheckpointID:            cpID,
			SessionID:               state.SessionID,
			Transcript:              redactedTranscript,
			Assets:                  finalizeAssets,
			PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
			Prompts:                 prompts,
			Agent:                   state.AgentType,
			SkillEvents:             skillEvents,
			PrecomputedBlobs:        precomputed,
		}

		updateErr := store.Write(ctx, checkpoint.SessionTranscript(updateOpts))
		if updateErr != nil {
			logging.Warn(logCtx, "finalize: failed to update checkpoint",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", updateErr.Error()),
			)
			errCount++
			continue
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}

	// Clear turn checkpoint IDs unless another Stop can extend this turn. Do NOT
	// update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardToNewShadowBranch resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	clearFinalizedTurnCheckpointIDs(state)

	return errCount
}

// filesChangedInCommit returns the set of files changed in a commit using git diff-tree.
// Uses the git CLI for faster performance vs go-git tree walks (lower constant factors).
// Falls back to go-git tree walk if git diff-tree fails, since an empty result would
// break downstream condensation and carry-forward logic.
func filesChangedInCommit(ctx context.Context, repoDir string, commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
	var parentHash string
	if commit.NumParents() > 0 {
		parentHash = commit.ParentHashes[0].String()

