 	root, err := os.OpenRoot(tmpDirAbs)
 	if err != nil {
 		return fmt.Errorf("failed to open tmp directory root: %w", err)
 	}
 	defer root.Close()

 	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
