    23		for _, tt := range []struct {
    24			name string
    25			size int
    26			tail bool
    27		}{
    28			{name: "64KiB", size: 64 << 10},
    29			{name: "4MiB", size: 4 << 20},
    30			{name: "70MiB", size: 70 << 20},
    31			{name: "70MiBTail", size: 70 << 20, tail: true},
    32		} {
    33			b.Run(tt.name, func(b *testing.B) {
    34				path := filepath.Join(b.TempDir(), "transcript.jsonl")
    35				data := benchmarkTranscript(tt.size)
    36				require.NoError(b, os.WriteFile(path, data, 0o600))
    37				response := testFinalAssistantMessage
    38				startPosition := 0
    39				if tt.tail {
    40					startPosition = bytes.Count(data, []byte{'\n'}) - 1
    41				}
    42	
    43				b.ReportAllocs()
    44				b.SetBytes(int64(len(data)))
    45				b.ResetTimer()
    46				for b.Loop() {
    47					snapshot, err := (&ClaudeCodeAgent{}).CaptureTranscript(context.Background(), agent.TranscriptCaptureRequest{
    48						SessionRef:    path,
    49						StartPosition: startPosition,
    50						FinalResponse: &response,
    51					})
    52					if err != nil {
    53						b.Fatal(err)
    54					}
    55					if len(snapshot.Data) != len(data) {
    56						b.Fatalf("captured %d bytes, want %d", len(snapshot.Data), len(data))
    57					}
    58				}
    59			})
    60		}
    61	}
    62	
    63	func BenchmarkCaptureTranscriptLegacyReady(b *testing.B) {
    64		for _, tt := range []struct {
    65			name string
    66			size int
    67		}{
    68			{name: "64KiB", size: 64 << 10},
    69			{name: "4MiB", size: 4 << 20},
    70			{name: "70MiB", size: 70 << 20},
    71		} {
    72			b.Run(tt.name, func(b *testing.B) {
    73				path := filepath.Join(b.TempDir(), "transcript.jsonl")
    74				data := benchmarkTranscript(tt.size)
    75				require.NoError(b, os.WriteFile(path, data, 0o600))
    76				b.ReportAllocs()
    77				b.SetBytes(int64(len(data)))
    78				b.ResetTimer()
    79				for b.Loop() {
    80					if _, err := (&ClaudeCodeAgent{}).CaptureTranscript(context.Background(), agent.TranscriptCaptureRequest{
    81						SessionRef: path,
    82					}); err != nil {
    83						b.Fatal(err)
    84					}
    85				}
    86			})
    87		}
    88	}
    89	
    90	func BenchmarkAnalyzeTranscriptTurn(b *testing.B) {
    91		for _, tt := range []struct {
    92			name string
    93			size int
    94			tail bool
    95		}{
    96			{name: "64KiB", size: 64 << 10},
    97			{name: "4MiB", size: 4 << 20},
    98			{name: "70MiB", size: 70 << 20},
    99			{name: "70MiBTail", size: 70 << 20, tail: true},
   100		} {
   101			b.Run(tt.name, func(b *testing.B) {
   102				data := benchmarkTranscript(tt.size)
   103				startPosition := 0
   104				if tt.tail {
   105					startPosition = bytes.Count(data, []byte{'\n'}) - 1
   106				}
   107				b.ReportAllocs()
   108				b.SetBytes(int64(len(data)))
   109				b.ResetTimer()
   110				for b.Loop() {
   111					if _, err := (&ClaudeCodeAgent{}).AnalyzeTranscriptTurn(data, startPosition, ""); err != nil {
   112						b.Fatal(err)
   113					}
   114				}
   115			})
   116		}
   117	}
   118	
   119	func benchmarkTranscript(size int) []byte {
   120		content := bytes.Repeat([]byte("x"), 4<<10)
   121		line := append([]byte(`{"type":"user","message":{"content":"`), content...)
   122		line = append(line, []byte(`"}}`+"\n")...)
   123		finalLine := []byte(`{"type":"assistant","message":{"content":"Done."}}` + "\n")
   124		data := make([]byte, 0, size+len(line))
   125		for len(data)+len(line)+len(finalLine) <= size {
   126			data = append(data, line...)
   127		}
   128		return append(data, finalLine...)
   129	}
