235	func validateTranscriptSnapshot(ctx context.Context, data []byte, startPosition int, reconstructAssistant bool) (int, string, error) {
236		position := 0
237		latestAssistant := ""
238		var finalRecord []byte
239		remaining := data
240		for len(remaining) > 0 {
241			if err := ctx.Err(); err != nil {
242				return 0, "", fmt.Errorf("validate transcript canceled: %w", err)
243			}
244			line := remaining
245			if newline := bytes.IndexByte(remaining, '\n'); newline >= 0 {
246				line = remaining[:newline]
247				remaining = remaining[newline+1:]
248			} else {
249				remaining = nil
250			}
251	
252			linePosition := position
253			position++
254			trimmed := bytes.TrimSpace(line)
255			if len(trimmed) == 0 {
256				continue
257			}
258			finalRecord = trimmed
259			if reconstructAssistant && linePosition >= startPosition {
260				if !json.Valid(trimmed) {
261					return 0, "", errors.New("parse transcript record: invalid JSON")
262				}
263				// Claude's transcript is producer-owned compact JSONL. Most records are
264				// user/tool metadata; avoid allocating an envelope for records that cannot
265				// contain the assistant type value.
266				if bytes.Contains(trimmed, assistantRecordMarker) {
267					var envelope struct {
268						Type    string          `json:"type"`
